/* 2014年12月15日 文教委員会 会議録全文（正式会議録／公式会議録の転載）。scripts/minutes_fulltext.py で生成。 */
window.SHINAGAWA_DB.registerMinutes({"id":"h26-20141215-9","dateIso":"2014-12-15","title":"2014年12月15日 文教委員会","sourceType":"formal","sourceUrl":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=4842#one","fetchedAt":"2026-08-14","characters":53081,"voices":[{"i":1,"speaker":"こんの委員長","text":"○午前１０時００分開会\nただいまから、文教委員会を開会いたします。\n本日は、お手元に配付してございます審査・調査予定表のとおり、議案審査、請願・陳情審査、その他を予定しております。\nなお、本日、庶務課長が総務委員会における議案審査に出席するため、一時退席をいたしますことをあらかじめご了承願います。\n本日も効率的な委員会運営に皆様のご協力のほど、よろしくお願いいたします。\n────────────────────────────────────────────\n１ 議案審査\n(1) 第８８号議案 品川区立幼稚園条例の一部を改正する条例"},{"i":2,"speaker":"こんの委員長","text":"それでは、予定表の１、議案審査を行います。\n初めに、(1)の第８８号議案 品川区立幼稚園条例の一部を改正する条例を議題に供します。\n本件につきまして理事者よりご説明願います。"},{"i":3,"speaker":"今井制度改革・待機児童対策担当課長","text":"それでは、私から第８８号議案 品川区立幼稚園条例の一部を改正する条例につきましてご説明申し上げます。\nお手元に、委員会資料と、第８８号議案をご用意いただければと思います。委員会資料に沿ってご説明申し上げます。\n初めに、１の背景でございますが、平成２４年８月に公布されました子ども・子育て支援法におきまして、保護者が支援法第１９条第１項各号に掲げる認定を受けた上で、市町村が施設型給付の支給に係ると確認しました教育・保育施設を利用した場合、提供された教育・保育に要した費用を、子どものための教育・保育給付として支給する制度が新たに創設されたところでございます。この第１９条第１項の各号というのが、いわゆる１号認定子ども、２号認定子ども、３号認定子どもという分類になります。\n次に、２の改正の理由につきましては、このように、新制度におきましては、新制度に移行した幼稚園を利用し、子どものための教育・保育給付を受けるために、支援法第１９条第１項第１号に掲げる、これは条文の引用でございますが、満３歳以上の小学校就学前子どもとして認定を受ける必要があるが、現在の幼稚園条例には、その定めがないため、改正をお願いするものでございます。\n３の改正の内容につきましては、現在、新旧対照表にございますとおり、入園資格につきましては、区内に住所を有する満４歳以上から小学校就学の始期に達するまでの幼児とございますが、この前に、子ども・子育て支援法の第１９条第１項第１号に掲げる満３歳以上の小学校就学前子どもとして認定を受ける必要があることを加えるものでございます。\n次に、４の新旧対照表についてでございますが、今、入園資格の第２条のところはご説明申し上げましたので、裏面をお願いいたします。裏面の付則の子ども・子育て支援法の施行期日につきましては、子ども・子育て支援法の施行の日からとするということで定めるものでございます。\n５の子ども・子育て支援法施行の日は、平成２７年４月１日を予定しているものでございます。\nよろしくご審議のほど、お願いいたします。"},{"i":4,"speaker":"こんの委員長","text":"説明が終わりました。本件に関しまして、ご質疑等ございましたら、ご発言願います。"},{"i":5,"speaker":"南委員","text":"これは、満３歳以上の小学校就学前の子どもということに法律上はなるのだけれども、品川区の場合の区立幼稚園の対象としては、認定を受けた４歳以上の子どもが対象になるということでいいのですか。３歳の子どもについては、品川区の区立幼稚園は対象になっていないので、４歳と５歳になるという確認でいいのか、聞いておきたいと思います。"},{"i":6,"speaker":"今井制度改革・待機児童対策担当課長","text":"今、ご質問の新旧対照表の第２条にありますとおり、区立幼稚園につきましては、いわゆる４歳児クラスと５歳児クラスでございますので、法律上の認定は満３歳以上でございますが、これまでどおり、区立幼稚園につきましては、４歳児、５歳児のクラスで運営してまいります。"},{"i":7,"speaker":"南委員","text":"わかりました。\nそれで、例えば、４歳、５歳の子どもで、預かり保育、延長保育を受けたいという場合は、１号認定で対象になるということでいいのですか。"},{"i":8,"speaker":"今井制度改革・待機児童対策担当課長","text":"幼稚園の場合には、認定というのは、ご入園されてから認定を出すわけですけれども、出した１号認定子どもは、あくまでも幼稚園ですので、１号の認定を受けます。そして、預かり保育の部分は、地域子ども・子育て支援事業の中で預かり保育事業が規定されておりますので、１号プラス預かり保育事業という形になります。これまで通り、引き続き預かり保育を受けることができます。"},{"i":9,"speaker":"石田（し）委員","text":"１点だけ文言の確認なのですが、裏面の参考のところで、一番最後に、「満３歳未満の小学校就学前子どもであって」と書いてあるのです。満３歳未満は、明らかに小学校就学前ですね。日本において、飛び級制度はないので、３歳未満はみんな小学校就学前だと思うのだけれども、こういう文言というのは、どうしても入れなければいけないということがあるのですか。そこだけ確認させてください。"},{"i":10,"speaker":"今井制度改革・待機児童対策担当課長","text":"こちら、子ども・子育て支援法の参考の抜粋になってございますが、第９条の１号、２号、３号のところを見ていただきますと、第１９条の冒頭に「小学校就学前子どもの保護者に対し」という形で、全て小学校就学前子どもの保護者に対して、その利用について、下のように３号まで決めるものですと書いたところです。\n国のご説明等によりますと、今、飛び級制度というお話もありましたけれども、こちらは満３歳以上と満３歳未満を明確にするために、小学校就学前の子どもを２つに分類するための文言の形になります。今、満３歳未満は飛び級がないという話もありましたけれども、小学校就学前の子どもを満３歳未満、以上に分けているという形になります。"},{"i":11,"speaker":"南委員","text":"保育園の入園申請は、最近、大体１２月末までなのですけれども、幼稚園の入園申請はいつ頃の時期なのかと、認定を受けることと、入園の申請との関係がよくわからないので、改めてそこを教えていただきたいと思います。"},{"i":12,"speaker":"今井制度改革・待機児童対策担当課長","text":"区立幼稚園だけではなくて、今は新制度に移行する幼稚園がございませんので、幅広く国が規定しております。１号認定、いわゆる幼稚園を利用希望の場合のご説明になりますが、品川区もそれに準じております。１号認定の子どもの場合、保育の必要性で選考することではございませんので、それぞれの施設に直接利用申し込みをするというのは、これまで通り変わりません。そして、定員超過などがあれば、面接等の選考を経まして、入園の内定をした後に、認定の申請を、園を通して区にしていただきます。入園の内定をしてから、認定の申請を出していただきまして、改めて区から認定書をお出しするという形になります。\n区立幼稚園の場合には、入園の手続等については、例年通り変わっていないということです。"},{"i":13,"speaker":"南委員","text":"そうすると、直接保護者が幼稚園に入園したいのだという申し入れをして、申請を受けていただいて、内定がとれた段階で、園を通じて認定をとるという話なのですけれども、その過程では、保護者としての動きはなくて、具体的に幼稚園にお任せしておけばいいということなのですか。\nそのあたりと、各施設に申請を出す時期、内定がとれる時期がいつなのか、それを教えてください。"},{"i":14,"speaker":"今井制度改革・待機児童対策担当課長","text":"１号認定につきましては、保育の必要性がございませんので、国から簡素な手続という形で、園を通しての認定申請になっております。\nそして、区立幼稚園につきましては、先日も行いましたけれども、１１月上旬に募集にしまして、選考会をして、多い場合には抽選などをして決定しているところでございます。"},{"i":15,"speaker":"南委員","text":"わかりました。\nでは、最後に、保護者に対する新たな法律ができることによって、園を通してではあっても、認定を受ける必要があるというあたりの説明を、在園児と、これから入園しようという方については、この間の説明会が３カ所で行われましたけれども、在園児の保護者に対しての説明会というのは、どのような形で行われたのか、そのあたりを教えてください。"},{"i":16,"speaker":"今井制度改革・待機児童対策担当課長","text":"在園児につきましては、今後、１２月以降の保護者の説明会等で、各幼稚園長から説明をする予定でございます。"},{"i":17,"speaker":"こんの委員長","text":"まとめてください。"},{"i":18,"speaker":"南委員","text":"各園ごとに説明をするという理解でいいのですか。"},{"i":19,"speaker":"こんの委員長","text":"よろしいでしょうか。"},{"i":20,"speaker":"南委員","text":"いいのですね。"},{"i":21,"speaker":"今井制度改革・待機児童対策担当課長","text":"こちらは、幼稚園の保護者説明会等で、基本的には在園継続の形になりますので、その中で説明をさせていただく予定でございます。"},{"i":22,"speaker":"南委員","text":"わかりました。"},{"i":23,"speaker":"こんの委員長","text":"他にありませんでしょうか。"},{"i":24,"speaker":"高橋委員","text":"よくわからないので確認させていただきたいのですが、今、入園の仕組み、ここのルールが少し変わりましたけれども、来年の４月１日の時点で、区立幼稚園は、今までどおりの状況で運営されて、新システムに移行した新しい形の幼稚園にはならないという認識でよろしいですか。新システム上の幼稚園という形ではないのでしょうか。"},{"i":25,"speaker":"今井制度改革・待機児童対策担当課長","text":"まず１点、大変恐縮なのですけれども、今は新制度になりましたから、新システムという言葉は使っていません。区立幼稚園につきましては、新制度に移行してまいります。そのため、同じように認定を受ける必要があるという形になります。\nただ、区立幼稚園につきましては、来年度は、現行通りの運営形態で行ってまいりますということで、ご説明したところです。\n区立幼稚園は、新制度に移行しますが、私立幼稚園につきましては、平成２７年度は、移行する予定の園はないということでございます。"},{"i":26,"speaker":"こんの委員長","text":"よろしいでしょうか。"},{"i":27,"speaker":"高橋委員","text":"幼稚園ということで、認定子ども園にはならないということだと思うのですけれども、ならない際には、法律上、自動的に移行することになるので、留保という状況では申請しなければいけないというルールがあったような気がするのです。その辺の手続等をとられるのでしょうか。"},{"i":28,"speaker":"今井制度改革・待機児童対策担当課長","text":"委員ご指摘のみなし留保などは、今、私立園につきましては、幼稚園・保育園関係ないのですけれども、現在、認可を受けているところがみなし確認という形で、区の確認を受けたという前提で、来年の４月１日に移行するというのが、法の定めにあるところです。\n公立施設につきましては、認可という届出はございませんので、あくまでも国に届け出ているものでございます。これは、他の私立と同様にみなし確認の手続が必要ということではございません。"},{"i":29,"speaker":"高橋委員","text":"みなし確認の必要がないということですね。わかりました。ありがとうございます。"},{"i":30,"speaker":"こんの委員長","text":"他にございますでしょうか。\n他にご発言がないようですので、これで質疑を終了いたします。\nそれでは、採決に入ります前に、本件に関しまして態度を確認いたします。\nそれでは、自民党からお願いします。"},{"i":31,"speaker":"渡辺委員","text":"賛成です。"},{"i":32,"speaker":"こんの委員長","text":"公明党。"},{"i":33,"speaker":"つる委員","text":"賛成です。"},{"i":34,"speaker":"こんの委員長","text":"民・改。"},{"i":35,"speaker":"石田（し）委員","text":"賛成です。"},{"i":36,"speaker":"こんの委員長","text":"共産党。"},{"i":37,"speaker":"南委員","text":"はい。子ども・子育て支援法そのものについては、私たちは賛成できるものではないと思いますけれども、今回の条例については賛成です。"},{"i":38,"speaker":"こんの委員長","text":"無所属品川。"},{"i":39,"speaker":"吉田委員","text":"賛成です。"},{"i":40,"speaker":"こんの委員長","text":"無所属。"},{"i":41,"speaker":"高橋委員","text":"賛成です。"},{"i":42,"speaker":"こんの委員長","text":"これより、第８８号議案 品川区立幼稚園条例の一部を改正する条例を採決いたします。\nお諮りいたします。本件は原案のとおり決定することに、ご異議ありませんでしょうか。\n〔「異議なし」と呼ぶ者あり〕"},{"i":43,"speaker":"こんの委員長","text":"ご異議なしと認めます。\nよって、本案は全会一致で原案のとおり可決いたしました。\n────────────────────────────────────────────\n(2) 第８９号議案 品川区立教育センター条例の一部を改正する条例"},{"i":44,"speaker":"こんの委員長","text":"次に、(2)第８９号議案 品川区立教育センター条例の一部を改正する条例を議題に供します。\n本件につきまして、理事者よりご説明願います。"},{"i":45,"speaker":"村尾学校支援担当課長","text":"それでは、私から第８９号議案 品川区立教育センター条例の一部を改正する条例についてご説明いたします。\n資料につきましては、２枚つづりのものをご用意いたしました。\nまず、条例改正に至った経緯および組織再編成の必要性についてご説明させていただきます。\n現在、指導課内で教育センターの活用および機能の改善の必要性を感じ、平成２５年２月から、教育センターのあり方検討準備会を立ち上げ、協議が始まりました。そして、昨年度、平成２５年度の事務事業評価においても、学識経験者から、教育相談事業については、来談件数や相談件数が増加していること、また、学校現場の実情および相談の専門性の両面に精通した相談員の拡充が見込まれる。また、教育センター全体の業務および組織体制については、教育委員会事務局との関係を含めて見直すことが課題である。そのため、教育センターがセンターとして役割を果たすためには、情報収集から意思決定までの一元化を図るような中心組織となることが望ましいなどの意見が出されました。\n資料の１ページをご覧ください。教育センターにおける主な課題といたしましては、資料上段にありますとおり、指導課にある特別支援教育係やＨＥＡＲＴＳへの相談窓口と、五反田の教育センターにある教育相談窓口と複数あるため、情報共有ができていないという点や、組織が別々にあるための関係機関との連携が不十分であったり、また、相談件数の増加や内容の多様化・複雑化があり、さらには、平成２８年度からインクルーシブ教育への対応も現在求められているところがございます。\n今後、品川区のプラン２１ならびにルネッサンス、また小中一貫教育の推進とともに、教育課題であるいじめ防止をはじめとした健全育成や不登校対策、問題行動や非行への対処、学校内外でのトラブルや事故、そして、保護者や児童生徒からの相談の充実等、適切な支援体制の強化を図る、また、就学前および小・中学校における各相談や個別対応など、特別支援教育の推進なども進めていかなければならない現状がございます。\nこれらの課題を解決また改善していくため、現在の指導課の業務内容、方法、回数、規模、形態などを総合的に確認しながら、さまざまな話し合いを重ね、資料の真ん中あたりにあります再編成の枠のように、２つの組織編成を考えました。つまり、指導課の業務をただ単純に２つに分けて別々に行うというものではなくて、現在教育センターが持っている６つの面接室や５つのプレイルーム等、豊富な施設をより効果的に活用するとともに、特別支援、また健全育成や生活指導に関係する係と人員をセンターに集結させることで、今後ともより一層、さまざまな課題を効果的、また効率的に解決できる組織といたしました。\n次に、新しいセンターの組織についての簡単な概要でございます。現在の教育センターの名称を変更いたしまして、教育総合支援センターとして、課長職を置きます。\nそこで、まず、現在の指導課については、主たる業務は教職員の人事と服務、教育改革プラン２１、英語教育やＩＣＴ教育などの新教育施策を担当していきます。\n組織としては、統括・指導主事１名と、指導主事２名、教職員人事係、それから、現在、一貫教育推進担当の名称を事業推進担当と変え、そのまま指導課に置きます。そして、学校経営指導員も配置します。\n教育総合支援センターの主な業務といたしましては、教育過程、また学習・生活指導、安全教育、健全育成、不登校対策、特別支援教育など、教育活動全般および教員の研修や教育関係資料の収集管理等を担当しております。\n組織といたしましては、統括指導主事を１名と、指導主事を５名、特別支援教育係、学校支援チームＨＥＡＲＴＳ、そして、現存の教育相談センターの組織を残していきます。そこには、当然、今もありますけれども、適応指導教室も配置するという考えでございます。\nそれでは、資料下段にあるように、このような組織にすることによって見込まれる効果といたしましては、まず、先ほど課題で申しましたとおり、相談窓口と情報の一元化によって、情報の集約や迅速な対応ができるのではないかと見込まれる効果。また、センターの指導主事を中心に、関係組織による専門家を配置することにより、連携体制で課題を強化できる。そして、組織を再編することで、多面的、また多様力や機動力を高められるのではないかということがございます。\nもちろん、再編成に伴って業務が分割し、場所が２カ所に分かれるということについて予想される課題もございます。まず、指導課とセンターの情報の共有化が図れるのかどうか。また、業務がしっかりと運営できるのかどうか。特に緊急時など、連携した対応ができるのか等々ございました。\nそこで、来年度は定期的な意見交換や情報共有の機会や場として、指導課とセンターの課長や係長による週１回の合同ミーティングの設定をしたり、センターに配属する指導主事の指導課での勤務などを予定しております。\n特に緊急体制におきましては、万が一大きな事件や事故発生時には、指導課に緊急対策本部を立ち上げ、全体指示とともに、情報の集約や伝達、マスコミ対応などを担い、教育総合支援センターにおいては、現場に出向き、さまざまな情報収集と学校や児童生徒、保護者への対応を中心に行うなど、役割分担について、仕組みや方法、手立てなど、現在検討しているところでございます。\nいずれにいたしましても、運営上、さまざまな課題に対し、指導課、それから来年度設立するセンターが互いに連携を図りながら、相互作用が図れるようにしていきたいと考えております。\nでは、長くなりましたが、２ページ目をご覧ください。これまで説明した組織とするために、今回、品川区教育センター条例の一部を改正します。\n変更点といたしましては、まず、条例名が品川区立教育総合支援センター条例となります。第１条、第２条では、名称を変更するということでございます。\n第３条におきましては、係また組織等の移転に伴い、（２）から（５）まで、現在、指導課で行っていた業務が新たに加わってまいります。\n第４条では、指導主事を追加いたしました。統括指導主事もここに含まれます。\n第５条では、東京都という文言が外れました。\nそして、平成２７年度４月１日から施行ということになっております。\nこれで説明は終わります。よろしくお願いいたします。"},{"i":46,"speaker":"こんの委員長","text":"説明が終わりました。本件に関しまして、ご質疑等ございましたら、ご発言願います。"},{"i":47,"speaker":"渡辺委員","text":"説明資料の真ん中のところ、平成２７年度からの指導課とセンターを２つに分けられたところの中で、学校経営監がありました。この学校経営監の人員の配置や規模、これまでのイメージだと、学校経営監がいて、それぞれ担当というわけではないですが、学校であったり、地域性があったと思うのです。\nこの両立てである中では、どのような役割分担、人員の配置と考えられているのか、教えてください。"},{"i":48,"speaker":"村尾学校支援担当課長","text":"まず、それぞれ、学校経営監を配置した部分なのですが、最初に教育総合支援センターの学校経営監につきましては、当然、現在行っている学校の訪問とともに、教職員に対する研修として、さまざまな部分で経験を活かしていただきながら、特に初任者研修であったり、２年次、３年次、また、主管研修等にも参加していただくという形で、現在のところ、総合支援センターに２名から３名という考え方でございます。\nまた、指導課に配属する学校経営監につきましては、今後、英語教育やプラン２１を含めて、さまざまな施策がございます。そのときに、学校校長経験者ということで、いろいろな意見をしていただくとともに、さまざまな指導課での施策についてかかわっていただくという考え方でございます。"},{"i":49,"speaker":"渡辺委員","text":"校長経験者の方を中心としたこの役割は、すごく大きいと思います。これまでのいろいろな場の答弁等でも、若い先生方が増えている中で、ここはすごく頼りどころだと思っています。\nその中で、最後に指導課のところで、規模もありますが、全校的に見渡すのか、あるいはどこかを特化して、拠点校のような形をイメージされているのか、一貫校の施設一体型なのか、分離校、連携校なのかなど、その辺の区分けは、特段あるわけではないのですか。規模と役割といいますか、その辺をもう少し詳しく伺えたらと思います。"},{"i":50,"speaker":"村尾学校支援担当課長","text":"特に指導課に来ていただく学校経営監の先生方については、基本的には全て区の中の学校を見ていただく。その中で、学校にもさまざまな課題がございますので、そのときはピンポイントで入っていただくこともございます。\nまた、規模によりましては、その都度さまざまな課題に対して、当然、学校経営監１人で動くのではなくて、指導主事であったり、さまざまな係と連携をしながら進めていくということで、特にピンポイントや狭い部分、一貫校または分離校という区分けで経営監の対応は考えておりません。"},{"i":51,"speaker":"こんの委員長","text":"他にございますでしょうか。よろしいですか。"},{"i":52,"speaker":"南委員","text":"まず始めに、資料を事前にいただき、読ませていただきました。今日、ここでさらに詳しく説明をいただいたのはよかったのですけれども、あまりよくメモもできなくて、ペーパーでいただければよかったかなと思ったりしました。その辺の配慮は、今後お願いしたいなと思います。\n指導課の中にあった事業、事務の中身を強化するということで改編するのだという趣旨はわかりました。相談体制を一元化するということで、子どもももちろんですけれども、保護者あるいは教員サイドから見たときには、一元化するということは、あながち悪いことではない。むしろ利便性にとってはいいのかなと、少し思ったりもするのです。\n１つ確認しておきたいのは、今まで情報が共有しにくかったので、そのようにしたのだということですけれども、相談する方にとって具体的にどのような不利益があったと、事例があったら一、二教えていただきたいのです。そういうことが現実的に実感されて改編に至ったのだという理解になるわけで、そのあたりをひとつ教えていただきたいなというのがあります。\nそれと、いろいろな保護者の方からも聞いてみたときに、１つになるから、それはよかったという話は、私も直接伺えました。ただ、これは教員サイドだと思うのですけれども、今までは、１つの事例で、教育センターと教育委員会と２カ所に文書を出していたということがあったと。そういう点で、１カ所にまとまるのは非常にいいのではないかということなので、なるほどと理解はしたのです。今までの状況を改めて、簡単でいいですから教えていただきたいです。\nそれから、当然、今までのことですけれども、相談した中身が、例えば、教員から保護者に、こういうケースで困っていらっしゃるのであれば、教育センターに相談に行ったらどうですかというアドバイスをしたときに、保護者が子どもと一緒に教育センターを訪れて、いろいろな相談をする経過を追って、月に１回か、２カ月に１回だかわからないけれども、一定の期間、相談する場合も大いにあり得ますね。時間はかかるけれども、相談の中身と、相談を受けてきた経過の中での結論みたいなものが出た、それが現場にフィードバックされていなかったということで、今までそのようなそごもあったので、そこら辺もきちんと相談の中身、結論についても教えていただければ、現場の指導も非常にやりやすくなるのではないかという話も聞いております。その辺について、どのように見解を持っておられるのか。ぜひ、私はフィードバックすることも、ケースによっては、もちろんやらないほうがいい場合もあるかもしれません。でも、大体はやったほうがいいのではないかなと実感しているので、その辺の考え方についても、少し伺いたいなと思います。\nそれから、概要を見ると、相談件数は多いのか、少ないのか、この数字の評価はわからないですけれども、年間百五十二、三件ということですし、相談回数そのものも、平成２５年度は３,９００回となっている。こういう数字そのものがどうかということは、全然評価はできないですけれども、これだけの実態があるということなのです。\n大体、相談件数の中身というのは、どんな中身だったのか。大ざっぱでいいのですけれども、いじめや不登校など、どんなケースがあったのかというのを知りたいなと思います。\nそれから、今度、２つに分けて連携をとるという話は当然だと思うのですけれども、今まで同じ指導課のスペースの中に２つの事業が入り込んでいて、相談機能としては別々になっていたけれども、これから分けようとする指導課の事務と教育総合支援センターの事務ということで、１つのスペースの中に置いておいて、共有できていた。そこが、週１回の会議を持つとか、いろいろなミーティングを持ち、何かがあったら本部を立ち上げるという説明です。それはそれで大事なことだと思うのです。\n今までやってこられたうまい連携プレーが、離れることによって、週１回のミーティングをしなければいけないということになるわけで、分けることによってのデメリットをどう捉えていらっしゃるのかというのを確認したいなと思います。\nいくつかあるのですけれども、とりあえず、そういうことで伺います。"},{"i":53,"speaker":"村尾学校支援担当課長","text":"大きく５点、ご質問をいただきました。まず、１点目と２点目、さまざまな窓口や複数における具体的な事例等。２番目は、２カ所に資料が必要で送っている等につきましては、多分同じような内容だと思います。\n具体的な事例では、例えば、相談センターに保護者の方が相談されている。それと同時に、学校についても保護者が悩み相談をしているときに、ある意味、教育センターの情報は、保護者は一切学校に言わないでほしいというものも当然たくさんございます。ただし、必要に応じて、センターからは緊急性がある場合は伝えなければいけないのですが、その辺がうまく機能していなかった。窓口が２つあることによって、相談センターではお母さんや子どもに対して、こうしたらいいですよとアドバイスすることに対して、学校からは、また少し違うアドバイスを保護者にしてしまって、内容がずれてしまうということがございます。そういうことが複数。\nまた、場所が離れていますので、なかなかお互いが顔を合わせて相談することもできませんし、相談資料をかばんに入れて、センターから指導課に持ってこられるかというと、それも個人情報が危ない。もしかして落としたりすることもありますので、そのような物理的な問題と、また内容によって、それを学校に伝えるべきものなのか、または学校だけではなくて、スクールカウンセラーの協力を得なければいけないものなのか等、ちゃんとした確認がとれないまま、お互いがお互いの業務を一生懸命しているというところで、複数による情報共有が十分ではなかったということがございます。\n同様に、資料要求についても、学校から相談センターに資料を要求するときと、ＨＥＡＲＴＳや、指導課の指導主事に資料を要求するときがあって、もしかすると２カ所に資料を要求したかもしれないのですが、その辺も十分対応できるのではないかなと思っています。\nまた、３番目のアドバイスという点については、教員から保護者に、悩みがあったら教育相談センターという１つの窓口がございますということをお話しはしています。これについても、当然、各学校にはカウンセラーもいますし、特別支援コーディネーター等も配置しているので、そこときちんと相談した上で、教育相談センターという１つのものを保護者にお伝えしていくことは、現状たくさんございます。\nただ、一概に、何かあったらすぐに教育相談センターに相談してくださいというよりも、まず、教員や学校がきちんと対応した上で、やはりこれについては専門的な機関に見てもらったほうがいいと判断した場合は、そちらにアドバイスを求めるというのが現状になっております。\nそれから、４番目、教育相談における件数なのですが、学校生活における不登校や登校渋りが、一番件数としては多く上がってきています。その次に多いのは、家庭生活において、保護者が養育上の問題について相談をするケースが２番目に多くなっているところがございます。その他、子どもの発達障害に関するご心配の相談であったり、時に子どもの対人関係についてのご相談、また進路相談等々も相談として上がってきている現状がございます。\n最後に、２つに分かれたときの連携のデメリットというご質問でした。先ほども申しましたとおり、一番危惧するのは、情報をお互いが持っていて、それぞれ対応が違っていくのは、やはりおかしいだろうということもございます。当然、先ほどお話ししたとおり、週１回ミーティングをやらなければならないではなくて、やることによって、より指導課とセンターが、お互いにそれぞれの事業を理解し、また、必要に応じて、共同で取り組むべきものもあります。またそれぞれの立場でアドバイスをしたり、相互作用や相互補完ができる体制をとっていくということが大きな前提でございます。その点につきましては、離れたから業務が滞ることがないように、こちらとしても十分配慮していこうと考えているところです。"},{"i":54,"speaker":"南委員","text":"私は、一元化することによって、相談しやすくなるというところは大事に考えておきたいなと思うのです。ただ、本課である第二庁舎の教育委員会指導課と、出先になる、課として位置づけるということであっても、場所が離れることによって、今まで以上の意思疎通や情報共有が、それはそれとして必要になってくると思うのです。\nだから、今まで以上に、お互いにしっかり意識して連携していかないといけないのではないかなという心配があるので、どうかなと思っていたのです。そういうことで理解できますということを、改めて紹介していただければいいかなというのが１つあります。\nそれと、先ほどのご答弁で、学校からの指導とセンターの指導が違う場合があって、親に対する指導が違う。それについては、教育総合支援センターになっても、学校と教育相談センターの関係は今と同じなわけですから、それは変わらず、そういう問題が起こる可能性はあり得ます。もちろん、そんなことはあってはならないと思うのです。だけど、そこが解決できるとは、私はならないのではないかと思います。\n違う指導が１つの保護者、子どもに行くということが、絶対あってはならないから、それはきちんと今まで以上に、今は学校に言ってはいけない情報や、ケースによっていろいろありますので、その辺の判断は、当然ご専門の方々ですから、そういうことは承知の上でされます。要するに、学校の先生たちが行きっぱなしで、今どうなっているのだろうという状況ではなくて、もう少ししたら報告しますとか、今ここまで来ていますとか、そういう現場と教育委員会、あるいはセンターとの共通認識が、きちんと１つ１つのケースでちゃんとしておくべきだと思うのです。ちゃんとしているとは思うのです。だけど、そういう心配が現実的にあるということですから、そこをなくすような努力は、ぜひしていただかなければいけないと思うのです。その点の確認をさせていただきたいなと思います。\nそれともう一つ、見込まれる効果の１点目に、「迅速かつ適切な対策を講じることができる」と述べています。同じことを繰り返すようになっているのかもしれないけれども、この辺の具体的な手立て、考えていることを教えていただきたいなと思います。"},{"i":55,"speaker":"こんの委員長","text":"よろしいですか。"},{"i":56,"speaker":"南委員","text":"はい。"},{"i":57,"speaker":"村尾学校支援担当課長","text":"３点ございました。まず、１点目ですが、委員がおっしゃるとおり、連携を図るということは、まさにこちらとしてもすごく大事なことであると思います。ただ、いつも全ての業務を連携して行うというわけではございません。それぞれ業務分担が分かれている中で、情報の共有については、意識的に進めていこうと考えているところでございます。\nまた、２点目なのですが、センターと学校、それぞれ１つの事例をご説明したのですが、何が変わるのかというと、１つは相談センターに入ってきたケースの中で、特に重要性であったり、少し重いケースについては、センターの中に指導主事、または特別支援教育係等が一緒にいますので、そこと情報を共有化できることによって、例えば、学校を巡回するスクールカウンセラーが様子を見るとか、また、担当している指導主事がその情報を受けることによって、学校とうまく対応できる形。それぞれ１本ずつ、学校は学校、センターはセンターで保護者に当たってきたものが、連携することによって、どういう対応のほうが、よりこの子にはいいだろう。または教育センターでは、どう保護者に指導、助言をしてきたかということを、学校を支える指導主事やＨＥＡＲＴＳ、またはスクールカウンセラーたちがわかることによって、それは別々の対応ではなくなるということが考えられるということでございます。\n３番目。迅速かつ適切な対策、手立てについてなのですが、当然、このセンターへのさまざまな情報は、ある程度、学校でのいろいろな事故や事件が発生した場合は、窓口になります。それを受けて、センターに指導主事、ＨＥＡＲＴＳ、特別支援関係であれば、特別支援教育係もありますので、一体どこの課が、どの部署が、どう対応していこうか。また、どこを連携してやればいいかということで、すぐに学校に出向くとか、その子についての情報を他の生活指導面で持っているかどうかということも、そこが情報を１本持っていますので、より迅速かつ適切な対処が今まで以上にできるのではないかと考えています。"},{"i":58,"speaker":"南委員","text":"最後に確認したいのですけれども、冒頭の説明で、指導課に係長を置く、週１回のミーティングをする、本部を立ち上げると、それだけのメモしかできなかったのですけれども、分けることによっての連携プレー、情報共有化を、どういう形で図ろうとしているかの説明が冒頭あったと思うので、もう一度そこを確認したいので、教えていただきたいというのが１つです。\nそれから、２つ目は、指導課には統括１人、指導主事２人、センターに統括１人、指導主事５人と配置するという話だったのですけれども、今現在の同じような流れで事務をとり行っている関係で見ると、指導主事は７人いらっしゃる中で、２対５の割合で、今度は向こうに持っていくのに５人置くのですけれども、同じような人数の配置でやって、どう変わるのか。分けることによって、今やっているこちらでの事業、事務の中身が、７人で変わらないのか。私は、これだけの規模を向こうに持っていってしまうのであれば、もう少し指導主事を増やしていいのではないかなと思うのですけれども、増やさないで現行でやるわけです。だから、今と分けることによっての事務量がどうなるのか。その辺を確認したいと思います。２点。"},{"i":59,"speaker":"こんの委員長","text":"１点目のことですけれども、これまで南委員がご質問された中に、全てお答えが入っていたという形だと思います。"},{"i":60,"speaker":"南委員","text":"もう一回整理します。"},{"i":61,"speaker":"こんの委員長","text":"その整理で、新たなところがあればお答えいただくのと、２点目は新たな質問なので、そこを整理させていただきます。"},{"i":62,"speaker":"村尾学校支援担当課長","text":"１点目、資料の真ん中の枠の網かけになっているところが、まさにこの組織の大きな役割分担を果たすと考えていくところでございます。ただ、緊急時の対応についても、先ほど委員からご質問がありましたけれども、繰り返しになりますが、基本的には指導課が緊急対策本部という形で教育長、次長のもとに立ち上がっていく。そこで、庁内での調整であったり、さまざまなマスコミ関係については、指導課を通して行っていく。それと、今度は、教育総合支援センターにつきましては、実際には現場に出て、現場での状況等を把握していくという、大きく２つの役割分担を果たしていきながら、きちんと明確化を図っていこうという流れで考えているところでございます。\n２点目ですが、人数を増やさないのはなぜかというところです。実際に、今やっている仕事を、それぞれ業務内容等に大きく分けるものですから、業務がぐっと膨れ上がるとか、もっと違うことをいっぱいしていくということではないので、現状としては、今の人数は変わらず行っていくという考えがございます。\n指導主事を２人または５人を配置という部分については、業務的な内容としてここに書かせていただいた内容を、それぞれ指導主事が、今現存して持っている業務がございます。それがセンターに移るに当たって、どれぐらいの人数が必要かということで、いろいろ協議をした結果、このような形である程度回せるだろうということになります。\n特に研修であったり、学校対応等に一番時間がかかり、また回数も増えるということもありますので、この２対５という割合で配置したというところがございます。"},{"i":63,"speaker":"こんの委員長","text":"まとめてください。"},{"i":64,"speaker":"南委員","text":"今の指導主事のところなのですが、回せるだろうということで、２対５にしたという話です。やはり一元化されることによって、多分、利用状況が増えていくのではないかなと思うのです。これからのことで、そういう状況を見ながら、学校への適切な指導、助言というのは、教育委員会の大事な仕事だし、指導主事の大きな役割を期待するところだと思います。必要な人員配置というのは、私は率直にしていくべきだと思います。\nこういうことでスタートするということなのですけれども、必要に応じて、その辺はきちんと対応していただきたいということを、あわせて申し上げておきたいと思います。"},{"i":65,"speaker":"こんの委員長","text":"他に。"},{"i":66,"speaker":"石田（し）委員","text":"１点だけ、行政サイドで組織を再編される、また窓口を一元化するというのは、私はすごくいいことだなと思います。逆に、保護者と児童生徒にとっては、若干混乱が生じる可能性もなくはないのかなと思うのです。今までここに相談すればよかったのに、それが一元化されることによって、例えば、窓口が変更になっているといった場合の混乱がないように、その辺の周知も含めて、相談する側にどうやって取り組んでいくのか。そこだけ確認させてください。"},{"i":67,"speaker":"村尾学校支援担当課長","text":"まさに来年度、それぞれの相談的なもの、また業務的なものが変わるということで、実際には年度末には各学校、児童、保護者用のリーフレットをつくらせていただいて、どういうときは、ここに窓口をつくっています。１本ありますから、ここに連絡してくれれば、こういう内容については、こちらで対応できますというリーフレット。また、小さい生徒が持てるようなカード的なものについても、今、検討しているところでございます。"},{"i":68,"speaker":"こんの委員長","text":"他にございませんでしょうか。"},{"i":69,"speaker":"つる委員","text":"今までの議論の中で、中身やルールなど、受ける側の児童生徒、保護者の方の立場に立って、一定の理解はできました。ただ、来年度からスタートするという中で、いろいろなことについては、これからというところだと思います。\nその中で聞きたいことは、どういう成果が期待できるのかというところです。課題や見込まれる効果の中には、課題を解決するためにこういうセンターを設ける、また、センターを設けたことで見込める効果の中で３点挙げられている迅速、そして適切な対策ができる、また、相談内容の状況に応じて、組織で連携協力することができる、そして、専門的・多面的な支援ができた結果として、どういう成果が期待できるのかというところがあると思うのです。アウトカムです。そういう部分について、これはなかなか数字的なことで見るのは難しいとは思うのですけれども、今ある課題に対し、より一層充実、拡充という、ふわっとした言い方はできると思うのですが、もう少し具体的な、これをやることでどういう成果を期待しているのかという部分を教えていただきたいと思います。"},{"i":70,"speaker":"村尾学校支援担当課長","text":"先ほどご説明したとおり、下の方でこういう効果が考えられる、そこの延長線上の成果という部分だと思います。まさに、来年度１年間やっていく中で、さまざまな課題は出てくると思うのです。こちらとして少し考えていかなければいけないのは、学校、管理職も含めて教員の人たちが、センターにそういう窓口が一本化し、組織が一緒になることによって、例えば、学校でトラブルや問題が発生したときに、これよりも素早く対応できるようになってきたのではないか。また、児童についても、相談窓口は１本で、さまざまな対応をすぐに学校へ、また、ＨＥＡＲＴＳが派遣されたり、学校を通してやっていく等、来年度、どういうところに成果が見え、どこにまだまだ課題が見えるのかというところを確認することが、まず１年目にこちらとして持たなければいけない１つの成果という部分かなと思っています。"},{"i":71,"speaker":"つる委員","text":"これから始まることについて、あまりどうのこうのと掘り下げはしませんけれども、今ご答弁いただいたように、始められての初年度というのは、そういう課題が新たに出てきたり、今後どういう成果が見込めるのかというのは、ステップアップして、それぞれつくっていくものだと思います。今後進める中にあって、一定の成果をどういうふうにして、ある意味で勝ちとっていくのかというところもきちんと明確にして、センターを設けたことによって、具体的にこんな変化が出てきたということを、また文教委員会の場でもご報告いただけるような形をとっていただきたいなと思います。\nそれと、あともう一個が、効果の一番最後の３点目のところにある、来年度から、いろいろやることによって、都内トップレベルの教育施設になる。トップではなく、トップレベルです。私も事前に調べることができなかったので、今回、センターを設置するに当たって参考にされた自治体の施設があれば、今後、自分自身も品川区がこれを取り組んでいくに当たっての比較検証を含む上でも、あれば教えていただきたいと思います。"},{"i":72,"speaker":"田村教育次長","text":"成果の話ですけれども、本来だと、不登校の数を減らします、あるいは、いじめの件数を減らしますという約束事をするのが成果という考え方も１つあるのですけれども、教育総合支援センターをつくったというのは、現実問題として、ＨＥＡＲＴＳが指導課内にできて、相談窓口が分散化していたのです。そうすると、先ほども南委員がおっしゃっていたように、相談のケースでは２通りあります。\n１通りは、学校に言ったけれども、対応してくれなかった。だから、学校には内緒で相談してくださいというケースが現実にある。ところが、それとは逆に、学校の教員の人事等、学校の教員の指導の仕方が不十分なので教室内が荒れているという話の相談。人事と相互に連携しないと、解決の糸口がつかめないという相談と２つあるのです。\nそれで、一緒くたに語ってしまうとごちゃごちゃになってしまうのですけれども、今回は、いずれにしろ、相談窓口を一本化して、学校現場、校長会とも何回も打ち合わせをしていますから、有効活用してほしい、相談窓口を一本化することで、有効活用してほしいということで、一本化しました。\n一本化すると、ご存じのとおり、今まで分散化していたＨＥＡＲＴＳのメンバーも、特別支援係も教育総合センターに移るわけですから、連携しながら、子ども一人ひとりに対応できる。きめ細かな対応が迅速にできるというのが１つのメリットであります。\nただし、それと相反する課題とすると、１つの課ができるわけですから、今まで指導課内に担当課長なり、教育センターは係でしたから、それとの連携は、統括する課長が１人だったので、そこで集約できたものが、発端はいいのです、できたときは、経過を知っているのですけれども、５年たち、何年たちというと、今度は組織のはざまで、指導課で対応してくれていたのではないか、あるいはセンターで把握して対応していたのではないかということが、当然出てきてしまうのです。何が一番の課題かと言ったら、いじめや体罰もそうですけれども、事故で苦しんでいるお子さんを救おうというのが一番の目的です。\nですから、相談件数が増えた、減ったは、全く私どもは関知していないというより、多くても、有効活用されて、死に至らないケース、あるいは学校に不登校の結果に至らないケースを１つでも食いとめれば、今回の教育総合支援センターの効果の１つなのかなと思っています。ぜひその辺をご理解いただいて。場合によっては窓口を一本化しても、指導主事もいるし、相談は指導課に来ます。こちらの本庁に、人事権を持っている指導課に相談が来るというのも、保護者のほうで当然あります。\nやはり、その辺の連携を密にして、最終的な成果というのは、苦しんでいるお子さんを１人でも救いたいということでございますので、ぜひご理解いただきたいと思います。"},{"i":73,"speaker":"村尾学校支援担当課長","text":"区によっては、本当にさまざまな形態をとっているというのが現状なのですが、実際にいくつかの区の視察も行かせていただいた中で、１つにはそこに常駐する、いわゆる統括指導主事であったり、所長が兼務しているということが多くて、何かするときには、いつもそこにいるわけではなくて、ここで言うと本庁にいるという課題があるということも、お話を聞きました。\nまた、実際には、大体のセンターでは教育相談窓口を開いていて、退職校長たちもいるのですが、実際にそこにＨＥＡＲＴＳ的な、いわゆるソーシャルワーカーを置いているところもあるのですが、置いていないところもあったりということで、いろいろなところを見ながら、センターの業務をする中で、どういう人たちがそこにいると、いろいろな部分がより一本化できるのかなということで参考にいたしました。\n例えば、目黒区や杉並区にも行って、それぞれの区のとてもいい部分、課題について知らせていただいて、現在、このような組織体制を考えていこうということであります。\n課長級を置くところも少ないです。"},{"i":74,"speaker":"つる委員","text":"今の後段は、ありがとうございました。よきところをそれぞれピックアップして、トップの施設というか。先ほど次長にご答弁いただきましたけれども、本当に学校の本来ある目的、教育の場であるところでなされることが、当然のごとくなされているというのが、本来あるべき学校の姿であるわけです。学校自体が社会の縮図であるわけですから、当然、今、次長からご答弁いただいたような、さまざまな課題が同時並行であるわけです。それについて、学校教育の現場の中で教えていただくこともあり、その中で児童生徒が学んで、また社会に出ていくということもあるわけで、それはそれで必要な中で、一番最後におっしゃられた、１人でも救っていきたい。これが非常に大事なことであると思います。\n当然、対処しては、また湧いてきてということは、多分ずっと続いていくのであろうと思うのですが、特段、こういう形で設置して、さまざまな自治体のよきところを参考にされながらやったわけですから、そういう部分でも、表向きにはこのようにできたと数値化できるもの、できないものがあるでしょうし、お子様一人ひとりの何をもって成果というのは、問いかけていかなければわからない中であります。\nその中で、小学校・中学校で児童生徒の方が、本当に生き生きと、本来当然あるべき当たり前の姿でもって教育が受けられる環境を充実していただきたいと思います。"},{"i":75,"speaker":"こんの委員長","text":"他にございますでしょうか。"},{"i":76,"speaker":"高橋委員","text":"２つあって、１つは、先ほど少しお話が出たのですけれども、このように仕組みが変わったというときに、効果があるようにするには、保護者の方やお子さんたちの話も出ましたけれども、先生方に仕組みが変わって、あそこからこういう話が出たけれども、それは今どうしてなっているのかという認識を持たれると、新しくいい方向に向かおうとすることも、なかなか現場に浸透していかないと思います。これは要望ですけれども、この仕組みでこのように変わるということを、現場の先生方に浸透させていただきたいと思います。なかなか時間がかかると思うのですが、よろしくお願いします。\nもう一つは、先ほど課長級云々の話がありました。人事の話なので、どうなのかあれなのですが、こちらのセンターの課長になられる立場の方というのは、いわゆる東京都から派遣されてくる方なのか、それとも行政の方なのか、仕事の内容によってもあれなのですが、仮に教員の経験のある方だとすると、２人いらっしゃる形になると思うのです。その辺は、先ほど５年後、１０年後というお話がありました。東京都と継続して、そういう体制をとるべきだと思うのですけれども、とっていく状況になるのでしょうか。これも先の話なので、「なるのでしょうか」と言うのは変なのですけれども、そういう体制についての見込みはどうなのでしょうか。"},{"i":77,"speaker":"田村教育次長","text":"今も、指導課長も都にお願いしてきてもらって、学校支援担当課長も校長です。ただ、私どもの希望とすると、そうしたいのですけれども、相手方のあることなので、東京都に希望を伝えて、できれば学校経験のある教育職で配置したいということです。必ずしも、それに固執しているわけではありません。\n前も小中一貫担当課長で、行政職で経験のある者がいたのですけれども、行政職でも学校現場との連絡や実務経験で、行政は行政なりのノウハウを持っていれば、何でも学校経験者が全ていいのかなというのはあります。当面は東京都にお願いして、そういう配置が可能なら、ぜひそのようにしていきたいと考えております。"},{"i":78,"speaker":"こんの委員長","text":"他にございますでしょうか。"},{"i":79,"speaker":"吉田委員","text":"先ほど次長から指導課とセンターとのはざまのことに関してお話があったのですけれども、うまく聞き取れなかったので、少し詳しいご説明を。\nそれと、緊急時の対処のことはこれからの話ということなのですけれども、いろいろな緊急時があるのですけれども、例えば、ここからこう行ってというような、どういう方向できっちりした連絡方法をこれからつくっていくのか、大体の具体的なイメージがありましたら、その２点をお願いします。"},{"i":80,"speaker":"田村教育次長","text":"最初のほうは現実にあった話なのです。先ほども具体例を話したのですけれども、拡大ＨＥＡＲＴＳという会議が、月１回あって、教育長も私も出て、それぞれの特に具体的なケースをやりとりしています。いじめだけではないのですけれども。当初は、教育センターがかかわっていなかったのです。相談者にしてみると、教育センターといっても、指導課内の１つの出先組織ですから、そちらに相談していれば、何らかの形で情報が共有化できて対応してくれるのではないかなと期待して相談している人と、もうそこを遮断して、あくまでケアのために相談しているという２通りがあります。\nそこは、もちろん私たちが十分に個人情報に配慮しながら、１つの行政の組織の中で相談しているものだったら、やはり共有化して、迅速に対応しなければ、命にかかわる問題であったりするケースがあるので、年度途中から、これはおかしいでしょうということで、教育センター所長も一緒に出なさいということで、情報を共有化してきて、今現在は参加しているので、その連携が今までは十分とれていない部分であったのかなと思います。\nそれと、緊急時対応は、私はずっとこの仕事をやっていますけれども、事故、事件、自殺の対応です。学校対応は、先ほど村尾課長が話していたように、学校との連携は、相談が来ているのは、今度の新しい組織になるので、やりとりはいいのですけれども、もっと大きな話になります。事故、事件があると、警察からの問い合わせ、マスコミからの問い合わせ、学校での保護者対応、学校のプレス発表なり、そういうものをどうするか。あと、議会の対応です。その辺は、教育長と私のもとで実際に動かないと、出先の組織で対応するというのは、実際には不可能だと思います。\nですから、そういうときには、先ほどの説明にもあったように、統括指導主事、あるいは課長自体が教育委員会、本庁に詰めて、それぞれ教育総合支援センターと連絡をとりながら、現在の状況を把握し、教育長と私から指導課長と学校支援担当課長を中心に、学校とも連携をとって、日々せめぎ合いになりますので、そういう対応をする。そういうケースがないことを祈っているのですけれども、１万７,０００人の子どもを抱える教育委員会とすると、想定として考えておかなければいけないだろうということで、そんな対応を今考えているということでございます。"},{"i":81,"speaker":"こんの委員長","text":"他にございますでしょうか。\n他にご発言がないようですので、これで質疑を終了いたします。\n採決に入ります前に、本件につきまして、態度を確認いたします。\nそれでは、自民党。"},{"i":82,"speaker":"渡辺委員","text":"賛成です。"},{"i":83,"speaker":"こんの委員長","text":"公明党。"},{"i":84,"speaker":"つる委員","text":"賛成です。"},{"i":85,"speaker":"こんの委員長","text":"民・改。"},{"i":86,"speaker":"石田（し）委員","text":"賛成です。"},{"i":87,"speaker":"こんの委員長","text":"共産。"},{"i":88,"speaker":"南委員","text":"意見を言わせていただいていいですか。"},{"i":89,"speaker":"こんの委員長","text":"はい。"},{"i":90,"speaker":"南委員","text":"いろいろ質疑を伺ってきたのですけれども、来年４月から地方教育行政の組織及び運営に関する法律が施行されるということで、教育委員会の根本的な性格が変わったわけではないのですが、住民自治という、地域、そして保護者、子ども、教員という方々の思いをしっかり受けとめて、５人の委員による教育委員会での議論がされていくべきものであって、そこは本当に大事にしていただきたいと思うのです。\nそういう中で、品川区は中身については、私たちもいろいろ問題を感じている部分はあるけれども、品川区の教育改革に取り組んできたわけです。そういう教育改革をするに当たって、５人の教育委員のところでも議論されて取り組んできたのだと思います。やはり、住民目線で議論していただくということを、あえてこのときに表明し、お願いしておきたいと思います。\nそれで、有機的な連携、ただ連携をとるのではなくて、本当にこの連携が効果のある、一人ひとりの子どもやいろいろな事例、学校指導に対しての有機的な連携をとるということを意識していただきたいということです。情報の共有に漏れがないようにするのは当然ですけれども、いろいろな職の人たちが集まって、１つ１つのケースをきちんとレファレンスし、そういうものを共有する会議をもって、共通認識を持っていただいて対応するということを強く求めておきたいなと思います。\nそういうことをお願いしておきながら、この条例については、率直に言ってすごく悩んだのです。利用する親や皆様の立場を考えたら、一元化ということはあながち悪いことではなく、利便性がとれる。先ほど言った有機的な連携をしっかりとっていただくということも含めて、頑張ってやっていただきたいということを強く申して、賛成したいと思います。"},{"i":91,"speaker":"こんの委員長","text":"無所属品川。"},{"i":92,"speaker":"吉田委員","text":"賛成です。"},{"i":93,"speaker":"こんの委員長","text":"無所属。"},{"i":94,"speaker":"高橋委員","text":"賛成です。"},{"i":95,"speaker":"こんの委員長","text":"それでは、第８９号議案 品川区立教育センター条例の一部を改正する条例を採決いたします。\nお諮りいたします。本案は原案のとおり決定することに、ご異議ありませんか。\n〔「異議なし」と呼ぶ者あり〕"},{"i":96,"speaker":"こんの委員長","text":"ご異議なしと認めます。\nよって、本案は全会一致で原案のとおり可決いたしました。\n────────────────────────────────────────────\n２ 請願・陳情審査\n(1) 平成２６年請願第２０号 品川区私立幼稚園児保護者負担教育費軽減の為の請願"},{"i":97,"speaker":"こんの委員長","text":"それでは、予定表の２にまいります。請願・陳情審査を行います。\nまず初めに、(1)の平成２６年請願第２０号 品川区私立幼稚園児保護者負担教育費軽減の為の請願を議題に供します。\n本件は、初めての審査でありますので、書記に朗読させます。\n〔書記朗読〕"},{"i":98,"speaker":"こんの委員長","text":"朗読が終わりました。\nそれでは、本件につきまして、理事者よりご説明願います。"},{"i":99,"speaker":"竹田保育課長","text":"それでは、平成２６年請願第２０号 品川区私立幼稚園児保護者負担教育費軽減の為の請願につきまして、ご説明させていただきます。\nまず、請願項目１の保護者補助金の所得制限の撤廃についてでございますが、保護者補助金は、私立幼稚園に通わせている保護者の方々の経済的な負担を軽減し、幼児教育を受けることができる環境を確保するという目的の制度でございます。このため、一定の所得制限が必要であると考えておりますが、区は従来から、私立幼稚園の保護者および私立幼稚園協会に対しまして、さまざまな経済支援を実施、拡充してまいりました。\n平成２２年には、保護者補助金の所得制限を緩和し、区民税の所得税額が２１万６,７００円から、２６万３,５００円までの方に対象を広げ、平成２４年度には、３３万４,１００円まで、さらに、平成２６年度には、３７万円までの方に対象を広げたところでございます。\nまた、就園奨励費につきましては、平成２６年度より、幼稚園に同時に就園している第２子以降と、小学校１年生から３年生に兄・姉がいる場合の園児保護者の所得制限を撤廃しております。今後も保護者負担の軽減と幼児教育の充実のため、教育費の家計に及ぼす影響や、保護者の方の負担の状況にも十分配慮しながら、適切な補助を行ってまいりたいと考えております。\nなお、平成２５年度の就園奨励金の受給者は１,３８１人、保護者補助金は２,１２１人、また、入園料補助金につきましては、所得制限はございませんが、１,２４６人の方に交付いたしました。これらの総額で５億２,２００万円余を補助しているところでございます。\n次に、２点目の、私立幼稚園へのさらなる支援・助成金の増額、また母の会連合会への助成金の要請でございます。現在、私立幼稚園に対する補助金といたしましては、幼稚園設置者に対するもの、私立幼稚園協会に対するもの、また各幼稚園の預かり保育事業に対するものの３点が主な補助対象でございます。\n各幼稚園設置者のための補助金といたしましては、運営費、研修費、教材費からなります振興費の補助金のほか、園児の健康管理増進費、心身障害児教育事業補助金、それから、防災安全対策補助金など、区単独で各幼稚園に対しまして、直接に補助しているところでございます。\n次に、私立幼稚園協会に対する補助金につきましては、特別支援教育の研修や講演などの充実を図るためなどに年額５０７万円を助成しているところでございます。そして、この中から母の会連合会の事業にも経費が充当されると伺っております。今後も子育てにかかる費用の経済的負担を軽減し、子育て世帯を経済面から支援し、安心して子育てをしながら住み続けられることを目指していくものでございます。"},{"i":100,"speaker":"こんの委員長","text":"説明が終わりました。本請願につきまして、ご質疑、ご意見等ございましたら、ご発言願います。"},{"i":101,"speaker":"南委員","text":"私立幼稚園に通っておられる子ども、年齢ごとに大体何人ぐらいいらっしゃるのか、まずそれを教えていただきたいです。\n現実的に、どのくらいの費用負担になっているのか。いろいろな保育料やスクールバスを利用されている方はそういう費用とかがあると思うのです。保護者の方の負担がどれくらいなのか。平均でいいのですけれども、何にどれくらいかを教えていただきたいと思います。"},{"i":102,"speaker":"竹田保育課長","text":"まず、人数のお問い合わせでございます。本年度の５月１日現在の数字でございますが、３歳児が１,０８７名、４歳児が１,０７０名、５歳児が１,０８３名で、合計３,２４０名でございます。\nそれから、負担の目安でございますが、私立幼稚園の保育料の全国平均でございますと、３０万８,０００円。品川区では、私立幼稚園の負担額は、月額２万６,７２２円、年額ですと３２万６６４円でございます。"},{"i":103,"speaker":"南委員","text":"人数はわかりました。\n負担の金額が、品川区の場合は３２万６６４円、これは総額であって、例えば預かり保育や保育料、その他スクールバスなど、必要なサービスを利用されている方は、また別個にかかっているのだと思います。３２万円の内訳は、保育料そのものだけと考えていいのですか。預かり保育やその他の費用というのは、別にかかっていると理解したほうがいいのですか。そのあたりを教えていただきたいと思います。"},{"i":104,"speaker":"竹田保育課長","text":"先ほど申し上げた数字は保育料でございますので、預かり保育等は、また別途、個人によって違うものでございます。"},{"i":105,"speaker":"南委員","text":"これも平均額でいいのですけれども、預かり保育料、スクールバス等々、私はこんなものしか思いつかなくて恐縮なのですが、もしそのほかにあれば教えていただきたいです。大体、保育料プラスアルファの部分の費用がどういうものがあって、いくらなのかを教えてください。"},{"i":106,"speaker":"竹田保育課長","text":"スクールバス等、園によって差がございます。申し訳ございませんが、今、手元に正確な数字は用意してございません。"},{"i":107,"speaker":"南委員","text":"わかりました。\n私は、それは、ぜひつかんでおくべきだと思います。こういう請願は、私立幼稚園母の会連合会から、ほとんど毎年のように出されている請願なので、つかんでおくべきだと思います。よろしくお願いしたいと思います。\nやはり経済的に、どこの家庭にも負担がどかっとかかってくるという状況がある中で、子どもを保育、あるいは教育する費用も負担が重たい１つの大きな柱になっていると思うのです。年額３２万円で、月額にすると２万６,０００円プラスアルファですから、小１万円かかると思うし、４万円近い金額が出てくる。その他に、衣料費等々がかかるわけです。したがって、豊かな、しかも健全な子どもを育てるという点では、１つの家庭の責任はありますけれども、社会的な責任という立場で捉えていく必要があると思うし、そういう認識を持っておられるから、いろいろな名目で、この間に補助金を出し、しかも拡充してきたと、私も理解しているのです。\nここに来て、やはり負担が重たいというところを、今、これだけの補助をしているから必要ないということではなく、今、これだけの負担がかかっていることに対して、品川区としてはどう認識していらっしゃるのか、そのあたりを伺いたいと思います。私は重たい負担になっていると思うのですけれども、そのあたりを区はどう考えているのか、質問したいと思います。"},{"i":108,"speaker":"竹田保育課長","text":"限られた財源で、保育にかかる経費を適正に配分するに当たっては、子育て家庭間の受益と負担の公平性を考慮する必要があると考えております。受益と負担のバランスを考慮した利用者負担のあり方を、今後検討するとともに、教育費が保護者の過大な負担とならないよう、適正な保育料の維持に努めていきたいと考えております。"},{"i":109,"speaker":"南委員","text":"私は、過大な負担とならないよう考えていきたいという最後のお話、見解が示されたので、それはそれとして受けとめておきたいと思っているのです。\nしかし、子どもを育てる保育にしても、幼稚園の教育にしても、子どもを育てるということは、未来への投資なのです。今、この時期にいくらかかる。確かに区の財政も豊かとは言っても限りがありますので、適正な金額は、どの場面においても考慮されるべきだと思います。\nしかし、未来の社会を担う子どもたちを豊かに健全に育てるという角度から、しっかりとした現状を見て、適切な配慮をするべきだと思うのです。そういう点で、過大な負担とならないようにというところを、どう理解したらいいのかが今の説明では不明なので、改めてそこを詳しく説明していただきたいと思います。"},{"i":110,"speaker":"竹田保育課長","text":"品川区では、東京都の補助に加えまして、区独自に補助金を出しております。今、その対象は園児保護者全体の７０％にまで拡大しているところでございますので、適切な支援ができているものと認識しております。\n今後も幼稚園で教育を受けたいと希望される方々の経済的な負担を軽減いたしまして、就学前の子どもたちに質の高い乳幼児教育が実践できるように、区としても全力で環境整備を進めていきたいと考えております。"},{"i":111,"speaker":"南委員","text":"最後に、適切な支援ができている。全園児の７０％だからというお話なのですけれども、私は保育料以外のさまざまな負担の内容をつかまないで、適切な負担ができているとは言えないと思うのです。ですから、そこをしっかりつかんでいただくということ。そして、ぜひ検討していただきたいと思います。\n私は、先ほども申したように、経済的ないろいろな状況の中では、一定の限度はあるとしても、母の会連合会の皆様が出された請願趣旨は理解できると思うし、未来への投資という点でも、やはりこれはもっと前進させていくべきだと思います。所得制限というのも、子どもを育てるという点では、私は外していくべきではないかなと思います。そういう点で、この請願については態度も言ってしまいますけれども、賛成していきたいと思います。"},{"i":112,"speaker":"こんの委員長","text":"他にございますでしょうか。"},{"i":113,"speaker":"渡辺委員","text":"私どもは、かねがね私立幼稚園の見解には強く、これまでの経過の中でもさまざまな支援をしてきています。議会としての要望も、当然ながら保護者負担の軽減を毎年強く要望するところであります。\nその中で、それぞれ年度により、また項目等がある中で、２つ目のところです。まず、母の会連合会の活動は、近年強く必要性を感じています。学校教育で言うところの、地域や家庭の連携の中で、特に家庭の自立についての支援というのは、必要性を強く思っていますので、最もであると。そして、また同時に、上の保護者負担の軽減のところの所得制限の撤廃については、同趣旨のことを議会としても場面、場面で行政とは折衝をしてきています。\nただし、一定の所得制限の必要性を行政側から説明を受けて、その中で、これまでも２年前、３年前と、対象の拡大を強くやって、結果を出せたということでもあります。\n現状において、先ほどご説明のありました、一定の所得制限の必要性と理由、あるいは今の区の考え方をまず伺いたいのが１つです。\n保護者負担軽減の直接的な保護者補助金ではなく、他の方法論を私たちも要望してきましたので、これまで保護者負担軽減をどんなことで取り組まれて、あるいは他のことも含めて、区がどう考えているのか、教えてください。"},{"i":114,"speaker":"竹田保育課長","text":"まず、財源等のご質問でございます。区は、さまざまな課題がある中で、限られた財源を保育に適正に配分できるよう努めているところでございます。各子育て家庭に受益と負担のバランスを十分考慮して、支援等を進めていきたいと考えております。\nそれから、どんな補助があるかというご質問でございますが、大きく分けて４つございます。保護者に直接補助するもの、あるいは幼稚園に対して補助するもの、あるいは各幼稚園に在籍されています心身障害児の教育に関するもの、それから、私立幼稚園協会に対する補助、大きく分けて４つございます。多角的にいろいろな場面から、保護者の方の経済的な負担を支援していきたいと考えております。"},{"i":115,"speaker":"渡辺委員","text":"もう一点、今のものに関連するのですが、一定の所得制限の必要性のところ。当然ながら、限られた財源であることは、もちろん承知しています。その中で、必要性のところは、区の考え方で、もう少し角度があるのかなと思います。その辺を知りたいというのがありますので、よろしくお願いします。\nそれと、下の母の会連合会の運営のところで、先ほど言った家庭の中で、保護者の方が一番求められている、私どもが聞き及ぶのは、正確な情報を得る手段、あるいは子どもと園との連携の家庭でのやりとりの中で、その質の向上を要望されています。母の会連合会の助成金の必要性に対する現状での区の考え方もあわせて教えてください。"},{"i":116,"speaker":"金子子ども未来事業部長","text":"今、委員から各種補助金についての所得制限のあり方についてのお尋ねがありました。この入園料補助金は、所得制限なしでやっている区独自のものですけれども、園児保護者補助金と就園奨励費補助金というのは、もともと国、あるいは東京都が所得制限でやってきているものであります。こういったものに関して、区としては、さらに保護者に対しての補助が必要であろうということから、上乗せという形で、かなり広範にこの補助をしてきた経過がございます。私ども、課長からるる申し上げましたとおり、やはり限りある財源の中で、一定程度拡充していかなければならないということで、ここまでやってまいりました。\n最近の動向としては、ご存じかと思いますけれども、幼児教育の無償化ということが国で考えられております。文部科学省の考え方、また政府の考え方がさまざまある中で、一定程度、所得制限つきで無償化というのが１つの案として出てきたことも承知しております。ただ、これが来年度の予算の中では見送られているという現状だろうと把握してございます。\nそういった中では、先ほど課長が申し上げたとおり、例えば今年、上の子が小学校３年生以下の第２子・第３子の無償化等々の国の考え方が示されています。その場合でも、国が全額を払うのではなくて、東京都、区も応分の負担をせよという内容で示されています。\nそういう意味では、今後、こういった動きも見ていかなければ、区の負担がかなり大きくなっていかざるを得ないのではないかと思います。私どもとしては、できる限り今後とも拡充していきますけれども、そういった財源のあり方を見ながら、両にらみという形で考えていかなければならないかなと考えてございます。"},{"i":117,"speaker":"こんの委員長","text":"他にございますでしょうか。よろしいでしょうか。\nそれでは、他にご発言がないようですので、これで質疑を終了いたします。\nそれでは、まず、本請願の取り扱いについて、ご意見を伺いたいと思います。継続にする、あるいは結論を出す、どちらかご発言願います。\nまた、結論を出すのであれば、その結論についてもご発言願いたいと思います。\nそれでは、自民党からお願いします。"},{"i":118,"speaker":"渡辺委員","text":"結論を出すということでお願いします。\nまた、態度については、趣旨採択が現状で望ましいと思います。\n理由を何点か。今のご質疑から、まさしく国の動向の中で、今ご説明があったとおり、幼児教育の無償化の検討のさなかで、私ども、強く推進している政党として、考え方があります。\nそれと、保護者負担の軽減というのは、こだわりの最たるものなのですが、対象者の問題もありました。これも、段階的に進んでいるこれまでの経緯もあります。その方法論の中で、私どもの会派として、いくつか優先順位を要望している中で、多子加算もそうなのですが、まだ直接的な補助金への所得制限の緩和よりももっと重要性のあるものがあるかと考えています。そういう意味では、方向性は一緒なのですが、タイミングを見たり、国を含めた動向を見る中では、ここが趣旨採択の理由の１つです。\nまた、それと同時に、思いとして、母の会連合会の支援の拡充の方向性は、この場を含めて強く要望したいと思っています。そのような理由から、趣旨採択であります。"},{"i":119,"speaker":"こんの委員長","text":"はい。次に公明。"},{"i":120,"speaker":"つる委員","text":"結論を出すということです。\n態度については、採択です。\n理由としては、今、議論がありました。当然、ご答弁の中でも、国の動向を注視し、昨年もそのようなご答弁がある中で、方向性としては、最終的に保護者負担の軽減という方向性に向かわせるためにも、もちろん動向を注視しなくてはいけないのですが、その中でも、この請願については採択という結論です。"},{"i":121,"speaker":"こんの委員長","text":"民・改。"},{"i":122,"speaker":"石田（し）委員","text":"我々としては、結論を出すということで、態度としては採択。\n理由としては、請願事項の１点目の部分では、教育費の負担の格差が拡大していると言われている中で、ぜひその軽減を図っていただきたいということで、採択としていただきたい。\nまた、２つ目の部分においても、教育内容の充実、また私立幼稚園の振興という意味では、ぜひ支援の拡大が必要かなと思いますので、採択ということでお願いしたいと思います。"},{"i":123,"speaker":"こんの委員長","text":"共産党。"},{"i":124,"speaker":"南委員","text":"私も、今日結論を出すことで、態度は採択にしていきたいと思っております。"},{"i":125,"speaker":"こんの委員長","text":"次に、無所属品川。"},{"i":126,"speaker":"吉田委員","text":"結論を出します。採択ということです。\nやはり国の動向ということもありますが、教育内容の充実という意味でも、これは進めていってもいいのではないかと思います。"},{"i":127,"speaker":"こんの委員長","text":"無所属。"},{"i":128,"speaker":"高橋委員","text":"今日、結論を出すということで、意見は採択です。\nなかなか経済状況が厳しい中、私立幼稚園に通わせている保護者の方々の経済的な側面から、特に保護者補助金についての所得制限は、先ほどの無償化の所得の話と、また少し違う話だと思うので、こちらは所得制限を撤廃して、負担を軽減していく方向で進めていくべきかと思っています。採択です。"},{"i":129,"speaker":"こんの委員長","text":"それでは、本請願については、結論を出すということで意見がまとまりました。そのような取扱いでよろしいでしょうか。\n〔「はい」と呼ぶ者あり〕"},{"i":130,"speaker":"須藤副委員長","text":"結論を出すということで、決められてきたのだけれども、この請願自体は、毎年来ているのです。それで、ある程度、ずっと趣旨でというのは、所得制限を撤廃することを議会で決めてしまうのは、逆に行財政改革特別委員会では、受益者負担も見直そうと、議会でやっているところです。そのようなものと、ここで撤廃することを議会でやってしまうというのは、品川区議会が両サイドに分かれてしまうことがあると思うので、自民党は趣旨でお願いしたいということで、お話しさせていただいたと思います。\nやはり、受益者負担というので、ずっと今まで所得制限を拡大してきているのは事実なのです。その中で、ある程度限度があるのではないだろうか。若い人を含め、所得を持っている人と、本当に格差があるという人は考えていかなければいけないということで、議会として、ずっと今まで趣旨採択としている。それを、行政と議会との話で、何年かかかって７割までの拡大をしてきているという経緯があるのです。\n先ほど来、皆様のお話を聞いていて、採択と言ってしまうと、行財政改革特別委員会では受益者負担という話もきちんとして、そちらの方向を見ていこうという議会の方向性と、同じ品川区議会としてのとり方が違うのです。私は自民党が言ったような形で、気持ちや趣旨の内容はよく理解するけれども、ストレートに採択にしてしまうと、今度は議会として、今まで受益者云々と言っておきながら、ここではそれをとってしまうというのは、二分性が出てきて、議会の方向性と違うのではないかなという思いがあります。委員長にお願いして、もう一度、そのあたりの議論を少しさせていただければと思います。"},{"i":131,"speaker":"南委員","text":"行財政改革特別委員会は、行財政改革特別委員会が主体性を持ってやればいいことで、文教委員会は文教委員会の質疑を通じて、皆様がそれぞれ態度を明確にしたのだと思うのです。もちろん、一番最初に自民党が発言した、そのことも踏まえた上で、各会派で態度を表明したわけです。ですから、私はそれを尊重していくべきだと思います。今、副委員長がもう一度議論をというお話でしたけれども、その必要はないと思います。"},{"i":132,"speaker":"こんの委員長","text":"今、自民党の副委員長からのご提案がありましたけれども、他にご意見。もう一度議論というところでのお願いがありました。南委員からご意見をいただきましたけれども、他はございますでしょうか。"},{"i":133,"speaker":"南委員","text":"そんなことをしたら、主体性がなくなってしまう。恥ずかしいことになってしまうと思います。\n今までのように粛々と進めていただきたいと思います。"},{"i":134,"speaker":"須藤副委員長","text":"ただ、今までも、この請願については、ずっと趣旨採択という形で進んできているのを、今回初めて、皆様方が採択ですと言うと、今までの流れと全然違ってしまうという意味で。"},{"i":135,"speaker":"南委員","text":"それは自民党の発言。"},{"i":136,"speaker":"須藤副委員長","text":"いや、そういう話は委員会で決めることだからということだけれども、それだけ重いものです。行財政改革特別委員会は行財政改革特別委員会だから違うのだということではなくて、品川区議会としての方向性はしっかりつくっておかなければいけないという懸念を私自身は持ちました。\nもう一度、皆様方の各会派で、少しお考えを見てもらえないかなと。議論しろということではなくて、そういう過去の請願に対して、どういう扱いをしてきているのだということを見たり、品川区議会として、行財政改革をどうとっているのだということを見たりして、正しい判断をしていかないと、はいはいと言うと、議会としてのありようが、少し違ってきてしまうだろうという懸念があります。\nこれは、ずっと趣旨採択でやってきて、所得制限は拡大をしてきている。これを外してしまうと、今度、国が無償化したときには、全部ということはあり得ないので、国も所得制限をかけてきます。そのときには、区が全部正式に持ち出すというか、一般財源を取り崩してやらなければいけないとなってしまうと、これは大きな話になってきてしまうと思うのです。その辺は、我々は議会として、先をきちっと見ながら、もう一度話を聞いていただいたほうがいいなと、私は思います。"},{"i":137,"speaker":"南委員","text":"今のような発言は、それぞれの態度を表明する前に発言したほうがよかったのではないか。２回、同じことを伺って、そう思いました。私の意見として申し上げたいと思います。\nそれから、副委員長が、もう一度、その辺を考慮してというお話でしたけれども、もちろん、それぞれみんな、その辺の今までの経緯も含めて考慮して発言しているわけです。したがって、この段階で議論して、ここまで来たときに、もう一度ということは、副委員長としては、職からしても、私はふさわしくないのではないかなと思います。\nそれと、３つ目。何回かそういう発言で、皆様に意見を促していらっしゃるけれども、出ないということは、副委員長のご発言については、なかなか難しいという判断があるのではないかなと、私は思いました。やはり粛々と進めていただきたいと思います。"},{"i":138,"speaker":"こんの委員長","text":"他にご意見がございますでしょうか。よろしいでしょうか。\nそれでは、副委員長からのご提案もありましたが、このまま進めさせていただくということでよろしいでしょうか。結論を出すという皆様のご意見と、今の自民党からのご意見も踏まえた上でということであります。他の方へのご意見を求めましたけれども、ないというところです。委員長としては、この状態の中では、どうですかと諮ってもないというところです。今の状況を見ますと、先ほど態度表明も伺い、ここで進めていくのがよろしいのかなと思います。\n逆に副委員長にお聞きしますが、よろしいでしょうか。"},{"i":139,"speaker":"須藤副委員長","text":"採択の仕方は２つ。趣旨採択する、採択するという、決のとり方もあるのだと思うのだけれども。"},{"i":140,"speaker":"南委員","text":"今までそういう経過はないです。ないと思います。"},{"i":141,"speaker":"こんの委員長","text":"そうすると、副委員長がおっしゃる、いわゆる趣旨採択、一部採択といった採決の方法がなくはないです。皆様の中で、採択、不採択、一部採択という、その表明の中で、どうするかという確認です。"},{"i":142,"speaker":"南委員","text":"今まで、趣旨採択も、採択も、反対ではありませんから、この気持ちは受けとめようという態度で、そんなに大きな違いはないと思うのです。例えば、相反する賛成と反対と、態度がそれぞれ分かれた場合、委員長の計らいとして、多いほうで決をとるわけです。この場合は、そんなに大きな違いはないですが、採択というところが圧倒的に多いわけです。採択と表明した委員が圧倒的に多いわけです。\nそれは、今までと同じようなやり方で進めていただいて、採決も今までと同じようなやり方で進めていただきたいと思います。慣行として、今までと違うものをやるべきではないと、私は思います。そこは、委員会運営の大事なところなので、皆様の意見を、ぜひ諮っていただいたほうがいいのかなと思います。私はそう思います。"},{"i":143,"speaker":"こんの委員長","text":"他のご意見ございますか。\n会議の運営上、暫時休憩いたします。\n○午後 ０時００分休憩\n○午後 １時００分再開"},{"i":144,"speaker":"こんの委員長","text":"それでは、これより文教委員会を再開いたします。\n休憩中に委員会運営の基本について、確認させていただきました。\n今までの先例によりますと、一事不再議の原則にかかりますので、採決は必ず１回しかできません。採択か、趣旨採択かで採決をとるというお話もありましたけれども、趣旨採択は、あくまでも採択の中の１つの種類という位置付けでございます。採択か、不採択かで諮るか、もしくは趣旨採択か不採択で諮るか、どちらかの方法で諮るしかないということでございます。\n今回は、採択の方が多かったということもありましたので、採択か不採択かで採決をとりたいと思います。よろしいでしょうか。\n〔「はい」と呼ぶ者あり〕"},{"i":145,"speaker":"こんの委員長","text":"ありがとうございます。\nそれでは、平成２６年請願第２０号 品川区私立幼稚園児保護者負担教育費軽減の為の請願を採決いたします。\n本件は、挙手により採決を行います。本件を採択することに賛成の方は、挙手願います。\n〔賛成者挙手〕"},{"i":146,"speaker":"こんの委員長","text":"全会一致でございます。\nよって、本件は採択することに決定いたしました。"},{"i":147,"speaker":"須藤副委員長","text":"今の中で、委員長がおっしゃったように、我々は趣旨採択ということでお話ししましたので、その意味での採択ということをご理解いただきたいと思います。"},{"i":148,"speaker":"こんの委員長","text":"はい。ご意見を賜りました。\n────────────────────────────────────────────\n(2) 平成２６年請願第２１号 認可保育園大幅増設で待機児ゼロを求める請願"},{"i":149,"speaker":"こんの委員長","text":"次に、(2)の平成２６年請願第２１号 認可保育園大幅増設で待機児ゼロを求める請願を議題に供します。\n本件は初めての審査でありますので、書記に朗読させます。\n〔書記朗読〕"},{"i":150,"speaker":"こんの委員長","text":"朗読が終わりました。\nそれでは、本件につきまして、理事者よりご説明願います。"},{"i":151,"speaker":"今井制度改革・待機児童対策担当課長","text":"それでは、私から本請願の項目、「認可保育園を大幅に増設し、待機児をゼロにしてください」についてご説明いたします。\n高まる保育需要と入園申込率に対しまして、品川区では、平成２２年度から平成２６年の現時点まで２,９７９人の保育の受入枠の拡大を行ってまいりました。そのうちのほとんどが、認可保育園の新規開設と定員の弾力化によるものでございます。\n待機児童ゼロというのは、区の政策目標の１つでございますので、引き続き認可保育園、そして認証保育所、小規模保育施設という新しい区の認可事業も含めまして、総合的な待機児童対策を進めてまいります。"},{"i":152,"speaker":"こんの委員長","text":"説明が終わりました。本請願につきまして、ご質疑、ご意見等ございましたら、ご発言願います。よろしいでしょうか。"},{"i":153,"speaker":"南委員","text":"認可保育園大幅増設で、待機児ゼロというのは、今、区民の切実な願いの１つだと思います。それを受けて、この間、私どもも主張してきましたけれども、区長も待機児をゼロにするということを公約されて、それに基づいて品川区もやってきたという経過があります。その辺の認識を改めて伺っておきたいと思います。\nそして、この請願に出ているように、認可保育園に空きはないということを訴えていらっしゃいます。それから、認証保育所は５０人、１００人待ちで、保育ママは満員である。認可外保育園は定員がいっぱいということを短い請願趣旨の中に訴えておられるわけです。こういう現状を、品川区としてはどう認識しているのか、まずそれを伺いたいと思います。"},{"i":154,"speaker":"今井制度改革・待機児童対策担当課長","text":"本会議でも答弁いたしましたとおり、待機児童ゼロというのは、私ども品川区の大きな政策目標の１つと認識しております。そのために、これまで総合的な対策で、他区に先んじて保育の受入枠の拡大をしてきたところです。\n現状につきましては、今、認可保育園の入園の申し込みという形で、定員の空き状況等をお示ししながら、申し込みの状況を確認していただきながら、今、申し込みを受け付けている段階でございます。\nなお、保育ママにつきましては、他区と違いまして、品川区が以前より入所調整しているものでございますので、新制度でも同じように、認可保育園と保育ママは同時に品川区が入所調整しているものです。\nまた、認証保育所につきましては、いろいろなご指摘を受けまして、今年８月から認証保育所の空き状況、そして来年４月以降の募集の時期が異なりますので、そのような情報をホームページに提供しているところでございます。\n認可外保育施設につきましては、東京都からの情報を、場所等についていただいているという形になっております。状況については確認しておりません。"},{"i":155,"speaker":"南委員","text":"私は、今、説明であったことも、それはそれとして大変いいというか、区の考え方、捉え方なので、それはわかるのですけれども、こういう状況にあるということを、どのように認識しているかと質問し、そこについての答弁がなかったので、そこはもう一度お願いしたいと思います。\nつまり、認可保育園を増設し、二千九百何人増やしてはいるけれども、現実的に空きはないということ。そして、認証保育所は、５０人、１００人待ちである。ホームページで紹介はしているけれども、今現在、５０人、１００人待ちの状況であるということ。あと、保育ママは増やしてきてはいるけれども、これも満員であるということ。そして、認可外保育園は、もう既に定員がいっぱいである。今現在こういう実態にある。こういう状況について、区はどう認識を持っているのかという質問をしたので、そこについてご答弁をしてください。"},{"i":156,"speaker":"今井制度改革・待機児童対策担当課長","text":"初めに、状況でございますけれども、「空きがない」という表現は、間違っていると思います。認可保育園の入園可能数については、ホームページに公表しております。それは、認証保育所も、一部でございますけれども、まだ空きがあるところもございます。来年の平成２７年４月に向けて、その募集について、ホームページ等で十分公表して、入園の申し込み状況についても公表しているところでございます。\n今回の待機児童が平成２６年４月に１２８人ということで、大幅に増加したことについては、重く受けとめております。"},{"i":157,"speaker":"南委員","text":"担当課長として、本当に大変なご辛労があるということは推察します。これからもできるだけ多くの区民の方たちにきちんとした保育要求に応えていただけるように、みんなで一丸となってやっていただきたいということを、改めてお願いしておきたいと思います。\nしかし、一方で、ここにも書いてありますけれども、「職場からの『いつ復帰するのか』との催促のたびに、リストラされるのかと恐怖が襲ってくる」と書いてあるわけです。これは、今年４月に入園に対して不服審査請求をされた６人のお母さんたちの共通する声です。\n私は、当時立ち会いましたので、本当に具体的な状況を受けとめて、深刻だと思いました。そして、私自身も働きながら子どもを育てて、保育園に預けるという体験もしてきましたので、本当に保育園に入れるのかどうか、自分が職場復帰をできるのかどうかという不安、それは体験してきましたから、痛いほどわかります。\nしたがって、ここに示されているお母さんたちの「リストラされるのかと恐怖が襲ってくる」というのは、本当に身につまされるような思いで読んでいます。何とか解決していかなければいけないということを思って、ずっとこの間、文教委員としても必要な発言をしてきたし、お母さんたちのそういう思いを一刻も早く解消しようと努力してきているつもりです。\n残念ながら、今、品川区は、待機児解消ゼロを目指すと言いながら、区立保育園をつくると言いながら、そういうことがなかなかできない。むしろ、姿勢は後退していると、私は思います。多様な保育をやっていくということで逃げようとして、公立保育園をつくってほしいという父母の願いに肩透かしをやろうとしていると思います。そこは、本当に怒りを感じます。\nこのお母さんたちの要求を阻んでいる元凶はどこにあるのか、誰なのかと、区長はそういう約束をして掲げているのに、そこが到達できないと肩透かしを食う。そんなことでいいのでしょうか。私は、このお母さんたちの恐怖は、本当に自分のこととして、しっかりと実現できるように求めていきたいと思っているのです。\n改めて、そこについて、こういう恐怖を感じているお母さんたちを、どう支え、子育てを一緒にしましょうと救っていこうとしているのか、その姿勢が見えません。担当の課長は本当に日夜努力して、いろいろな業者の方と話をして、できるだけ品川区で開設してくれとやっていただいていると思います。しかし、その努力を超える、大変に重たい阻む力があるのではないですか。そこが何なのかを、まず正していただきたいと思います。そして、それをなくそうという立場にしっかり立っていただきたいと思います。そういう認識があるのかどうかということを、私は聞いたのです。そこについても、ぜひ答弁していただきたいと思います。\nもう一つつけ加えさせていただくと、認可保育園が父母の一番重要な願いです。保育ママや認証保育園も、認可保育園に入るためのツールなのです。認可保育園に入りたい。それまでに、ここを経過すれば入れるのだとわずかに望んでいらっしゃるから、そこを通過するわけですけれども、本当は認可保育園なのです。そこを、事業者待ちだと、なかなかいかないから、区立でつくるべきなのではないかと言っているけれども、今は区立ではつくらない。つくっていないです。全然めどが立っていないです。何でそういう状況になっているのかということを、もう一度伺いたいと思います。"},{"i":158,"speaker":"今井制度改革・待機児童対策担当課長","text":"今、企業との関連でおっしゃいましたけれども、私ども、少子化対策というのは、これは逃げでも何でもありませんけれども、保育施策だけではなく、労働施策と関連しながら、やはり育休の延長や、そのような時間をとる、総合的な国全体での対策が大切だと考えております。\nその中で、保育の実施責任を負う品川区が、今していることというのは、国の補助金、そして都の補助金を受けながらも、品川区で大幅な加算をして開設にこぎつけている状況です。\n私どもは、ここでも書いておりますが、「いつでも、どこに住んでいても預けられる体制」ということで、全区的に、総合的な待機児童対策という形で、認可保育園や認証保育所、保育ママを地域的に広がりを持ってつくりながら開設を進めているところです。一定、区立保育園を定員を充足してつくっているところですので、今、判断としては、平成２７年７月に御殿山のところに、区立の幼保一体施設をつくるという計画を持っておりまして、区立の計画を全くしていないというところには当たらないと考えております。\n認可保育園に入りたいという保護者の方の思いは十分受けとめますけれども、まずは保育の受入枠の確保が重点的な目標だと思います。繰り返しになりますけれども、私どもは認可保育園、認証保育所、小規模保育事業など、認可基準となりました区の基準を踏まえながら、一体的に整備してまいります。"},{"i":159,"speaker":"南委員","text":"国の労働政策等々、あるいは企業の産休、育休、あるいは男性も含めた育休の体制がつくられているけれども、現実的にはきちんと機能され切れていないと思うのは、事実だと思います。\nしかし、それはきちんとした国の指導なり、東京都の指導なり、区の役割分担の中で、区は区としての指導も、必要なところはぜひやっていただきたいと思うのです。それが進まないからということも、待機児が増えている１つの理由になっていると思います。\nだから、そこを待ちではなくて、当面、そういう環境が整うまでの間、毎年待機児を繰り返すのかということになるわけです。そのようになってはいけないので、区も責任を持って、他力本願ではなくて、区が主体的に、リストラされる恐怖におびえるお母さんたちは、豊かな子育てなんてできないではないですか。毎日電話がかかってくるたびにはらはらどきどきして、夜も寝られない。乳飲み子を抱えて、寒空に保育園を探して歩く。こんなことをいつまでさせるのですかということです。\nもうそういうことをさせないときちんと決意してやっていくには、１００遍唱えても解決しないのです。解決させるには、品川区がきちんと自らが保育園をつくって、そこを救うための対策ですから、当面のでもいいです。一時的でもいいと思います。なぜそれをしないのかということを、１つ私は言いたいのです。それは、ぜひ答弁していただきたいと思います。\n今年に限らず、とりわけ今年４月の時点と、来年もそうですけれども、この間、質問で明らかになったのは、入園申請は大体何割増しで、２,７００人ぐらいになるだろうという状況が、たしかあったと思います。そういう２,７００人の子どもが入園申請をすることにフォローできるだけの体制はでき得ていないと思います。下の報告にあるけれども、認可保育園が２園、認証保育所が１園、保育ママ、小規模保育が２園ということで、これで可能な人数というのは、たしか２１４人です。\nもちろん認可保育園の空き状況もありますけれども、とても間尺に合わないほど待機児です。そのことを聞きますけれども、来年４月開設予定の認可保育園等々の２１４人の新たな枠プラス既存園で入園可能な人数は何人ですか。それで入園可能数はいくらになるのか。まず、そこを知りたいと思います。\nそして、まだ予測の段階ですから、２,７００人で足りるのか、オーバーするのかはわからないですけれども、今のところは大体２,７００人ぐらいとされている申請数は解消できるめどが立ってきていると見ていいのかどうか。そこについても伺います。"},{"i":160,"speaker":"今井制度改革・待機児童対策担当課長","text":"本会議でも答弁いたしましたとおり、明日報告いたします他に、現在でも、平成２７年４月に向けて、協議を進めているところはございます。ただ、発表に至るか、最終的にどのようになるかというのは、今検討中のところでございます。\n来年４月の受入枠の拡大については、今ご紹介のとおり、プラス、来年は、北品川第二保育園の４・５歳児枠の４０人が空きますので、こちらも含めますと一定の数が間に合うところです。ただ、待機児童数は増加する見込みと考えております。\nさらに、７月までに南品川の国家公務員宿舎の跡地と、先ほどご案内しました五反田第二保育園、御殿山すこやか園のところが開設いたしますので、あわせて４００人規模の開設を進めていく状況になっております。\n平成２７年４月の保育園の利用可能数については、１２月１日の公表でございますが、合計で１,３１８人ということで、公立、私立あわせての数をお出ししております。"},{"i":161,"speaker":"南委員","text":"１,３１８人プラス４００人ですから、１,７１８人という数字が入園可能数ではないかということで、４月１日の入園可能数は、１,７１８人と見ていいのですか。７月開設になっていると思っているので、１,７１８人でいいのかどうか、改めて確認したいし、４月１日時点の入園可能数は何人なのか。７月になったらプラスいくらと仕分けて、正確につかみたいと思いますので、そこのところを確認で教えていただきたいのが１つです。\n２,７００人前後だろうということなのですけれども、当然、単純計算で１,０００人ぐらい足りないという状況になるわけです。その辺は、どうしようとしているのか、その考え方についても伺いたいと思います。\nそれから、先ほどから聞いている「リストラされるのかと恐怖が襲ってくる」というお母さんの気持ちをどう認識しているのか。その辺についても伺いたいと思います。"},{"i":162,"speaker":"今井制度改革・待機児童対策担当課長","text":"まず初めに、保育園の利用可能数、こちらは予定でございますけれども、委員ご案内のとおり、例えば、特別支援児童が入ると、これより少ない人数しか受け入れられない場合もございます。一定、今公表している人数は１,３１８人でございます。\nそれから、４月の開設につきましては、今、認定子ども園、北品川第二保育園の４・５歳児が４０人、それから、私立保育園の新規開設が１４０人、認証保育所が４０人、小規模保育が３４人、それから、人数を最終確定するところなのですけれども、私立保育園の定員拡大につきまして、利用可能数以外にもお願いしている部分がございますので、来年４月の受入枠の拡大について本会議で答弁したとおり、２５０人規模と考えているところでございます。\n「リストラされるのかと恐怖が襲ってくる」という文言でございますけれども、リストラだけではなく、いろいろなご事情の中で、保育園だけではなく認証保育所などの保育の受け皿の期待が大きいという現実は十分受けとめております。"},{"i":163,"speaker":"こんの委員長","text":"そろそろまとめてください。"},{"i":164,"speaker":"南委員","text":"私はもちろん、今、課長がおっしゃったように、リストラだけではなくて、保育園に子どもを預けることができるのか、できないのかという不安は、この他にももっとあると思います。したがって、そういう声にきちんと応えていく。社会の宝として子どもを健全に育てる、社会的責任として育てるという立場に、さらにしっかりと立っていただきたいと思うので、そのように言うわけです。\nそういう点で、不安におびえるような状況をできるだけ少なくするには、やはり増設以外にないと思うのです。保育体制の充実を、ぜひしっかりやっていただきたいと思います。\nそれと、先ほど聞いたつもりだったのですけれども、あまりご答弁がないので、もう一回確認です。区立の保育園で民間任せ、他力本願の姿勢ではなくて、いろいろ努力していることは、具体的な対策で、人数も含めて説明がありましたので、それはそれとして伺ってはいるのです。それだけでは足りないということが現実的にはっきりしてきているだけに、やはり穴埋めとしては、こういう不安を解消するには、区立保育園を一時的なものであってもいいからつくるべきだと思っているのです。その点については、なぜやらないのか。やらない理由は何なのか。それを伺いたいと思います。"},{"i":165,"speaker":"今井制度改革・待機児童対策担当課長","text":"認可保育園の設置主体が平成１２年に株式会社も含め、多様な主体が認められている中、国でも新制度のところで多様な主体による事業の推進ということを、新制度でもうたっております。品川区は、保育所保育指針に基づいた一定の保育の質、そして同じ保育料の中で、これだけ充実した保育を公立、私立にも行っております。認可保育園が保育の受け皿の柱ということは議論の余地がないところですけれども、それだけではなく認証保育所、小規模保育を含めて、一体的な整備をしていくということが、大きな課題だと認識しております。"},{"i":166,"speaker":"南委員","text":"どうしても区立保育園をつくるということについての答弁ではないと、私は受けとめざるを得ないのです。したがって、同じことをずっと聞いて大変申し訳ないと思っているのですけれども、そこの回答が来ていない。多様な保育主体ということで来ていて。私が聞いているのは、区立の認可保育園でと言っている。一時的でもいいからということを言っているけれども、そこに対する答弁がないのです。もう一度聞きたいし、もうこれで終わりにしようと思っていたのですけれども、それはぜひ質問させていただきたいと思います。"},{"i":167,"speaker":"こんの委員長","text":"南委員の感じ方、捉え方ですが、私はご答弁を聞いていて、一定のご答弁が出ていると思います。感じ方というところで、もう一度繰り返しだけれどもしたいというお気持ちなのだろうと思うのです。それならば、もう少し角度を変えて話を聞くのか、本当に話が堂々めぐりになっていますので、そこら辺のところを、お話を整理するなりしていただきたいと思うのです。多分、皆様、他の方も今のご答弁を聞いていて、ある一定のご答弁があったのではないかと思われている方もいらっしゃると思います。"},{"i":168,"speaker":"南委員","text":"区立認可保育園をつくらない理由。多様な保育はやるという答弁はあるのです。だけど、多様な保育というところは、区立の認可保育園も含まれていると、私は理解できないのです。\n区立の認可保育園をつくってください。こんなにいっぱいある中、一時的な内容でも、暫定的な内容でもいいからつくるべきですという質問をしているのに対して、認可保育園と答えず、多様な保育と言っているのです。\n申し訳ないですけれども、本当に私の質問に対して、はぐらかしの答弁をしていると思うのです。そうではないと首を振っている部長、ちゃんとわかるように答えてください。"},{"i":169,"speaker":"今井制度改革・待機児童対策担当課長","text":"現在、品川区は４２園の区立保育園がございます。全部で、７３園です。来年、４３園目の五反田第二保育園を開設させていただきます。今、品川区で検討を進めている区立保育園というのは、平成２７年７月の区立保育園の開設となります。"},{"i":170,"speaker":"こんの委員長","text":"よろしいでしょうか。他にございますでしょうか。"},{"i":171,"speaker":"南委員","text":"納得していないです。もう一回、後でやります。"},{"i":172,"speaker":"こんの委員長","text":"よろしいですか。他にございませんでしょうか。"},{"i":173,"speaker":"須藤副委員長","text":"もうこれは堂々めぐりなので、早く扱いをやっていただければと思います。よろしくお願いします。"},{"i":174,"speaker":"南委員","text":"扱いをやれという副委員長のご発言なので、私は先ほどの続きの質問をさせていただきたいし、なぜわからないかというところを、少し説明させていただきたいと思います。\n今の担当課長の答弁では、区立保育園は４２園、私立も含めて、全体で７３の保育園があるというお話でした。そして、来年の五反田第二保育園がオープンするというお話でした。\n私の質問趣旨というのは、来年の３月、４月に入園する子どもが大枠で見ても、大体１,０００人ぐらい入れない状況になるだろうということです。それに対して、五反田第二保育園ができても、これだけの保育園の枠では入れないではないですか。入れないと思うのです。入れるのですか。入れるのかどうかを聞きたいと思います。\nそれで、私は入れないと思うので、暫定的でもいいから区立の保育園をつくりなさい。そういう考えはないのですかと聞いているのに、その答えは全然ないのです。多様な保育でやる。多様な保育というのは、皆様もご承知だと思うけれども、保育ママ、認証保育所等々です。多様な保育というのは、区立の認可保育園ではないのです。だから、先ほどから繰り返して聞いているのです。\n他の皆様は、課長の答弁で、私の質問に対して答えが出ていると思いますか。ぜひ私はここのところの意見を聞きたいです。そして、説明していただきたい。もう同じことを繰り返されているからいいのではないかと言われているのだから、どう理解しているのか、私は逆に皆様に聞きたいです。そして、ぜひ答弁していただきたいと思います。"},{"i":175,"speaker":"須藤副委員長","text":"答弁ではないのだけれども、待機児ゼロというのは、横浜市はゼロにした途端に、また次の年にばーっとなったというので、品川区だけゼロというのではなくて、もう少し近郊の区と連携しながらやっていかないと、私はそのあたりもきちんと整理していかなければいけないなという思いでいます。そのお考えはいかがでしょうか。目黒区や大田区などとの連携はどうなっているでしょうか。"},{"i":176,"speaker":"金子子ども未来事業部長","text":"先ほど来、るる課長が答弁してきた通りなのですけれども、こと東京都の状況、あるいは城南ブロックの状況を見てみますと、私どもは平成２２年度から待機児童対策を強化してまいっています。はっきり申し上げて、平成２２年、平成２３年の頃は、周辺の区はそれほど力を入れていなかったように思っております。\nところが、平成２４年、平成２５年になりますと、他区もかなり力を入れてきて、今お話がありましたとおり、横浜市、あるいは千葉市等々で待機児童ゼロと宣言しながら、単年度だけの結果になっているということが、１つには、供給が需要を生むということもありますし、かなり広域的に取り組んでいかないと、結局そこの自治体に集中する、あるいは人の流れがそちらへ向かうということになってしまいかねない。先ほど私どもが申し上げた数字も、それが１つの呼び水になって、こういう結果になっているのかなとも思っております。\n私どもとしては、区長も申し上げましたとおり、待機児童対策には積極的に取り組んでいく。手法としては、総合的に取り組んでいくと申し上げております。これは、認可保育園、認証保育所、保育ママ、新たな制度であります小規模保育といったことを総合的に取り組んでいきましょう、あるいは、企業の協力を得て、事業所内保育も含めて拡充していこうと考えております。\nこの場合に、設置者が誰かというお尋ねもありました。これは、第３回定例会の委員会でもご答弁申し上げているとおり、区立、私立も含めて検討して、その１つの結果が、先ほど課長が答弁申し上げたとおり、来年７月に五反田第二保育園を幼保一体施設として開設するということになっているわけでございます。今後とも、こういった考えのもとに、待機児童対策を進めていきたいと考えております。"},{"i":177,"speaker":"南委員","text":"今、部長が答弁されて、供給が需要を生むとおっしゃいました。これは、品川区がどんどんやっているから、子育て中の保育園に入れたい人が、どんどん品川区に集中しているという状況ではないわけです。どこの自治体にも、子どもを預けて、自分も社会参加したいのだという女性が、どこも増えているわけです。こういう現状というのは、品川区の特徴ではないでしょう。だから、供給が需要を生むということで、私はごまかすべきではないと思うのです。しっかりと需要に対して応えていくというスタンスを持っていないとだめだと思うのです。\nそれで、総合的に取り組むとおっしゃるけれども、総合的に取り組むことは、別に否定しないです。入りたいという子どもを受け入れられる体制をとるということですから、それはそれでよくわかるし、受けとめていきたいと思っています。\nしかし、先ほどから何回も言っているように、絶対的に足りないわけです。来年は、多分４桁の数字で足りなくなるのではないかと予想されるわけです。\nそれに対して、北品川、五反田第二保育園ができるからといっても、ここで入れる子どもは何人なのですか。４０人ではありませんか。１,０００人の子どもに対して、いろいろ全部やっても、１,７００人でしょう。全然足りないではないですか。\nだから、どうするのか。一時的でもいいから、区立でつくり、しのぐべきではないかということを言っているのです。それに対しての答弁が、全然はぐらかしで、北品川ができます、どこそこができます、そういう答弁でごまかさないでいただきたいと思っているのです。そこまで言いたくないです。区が一生懸命努力していることは認めていきたいと思っているから、ごまかしという言葉は、できるだけ使いたくないです。でも、本気で解消しようという姿勢が、どうも見えないのです。\nこの間までは信頼して、そういう方向で頑張ってくれているのだ。業者もいっぱい来ている、来年の４月は６園つくりますとなったけれども、結果的に、今この時点で全然ではないですか。１２月半ばの時点だと、３カ月半の間に待機児をできるだけ少なくしていくという姿勢に立つのであれば、区がしっかり責任を持ってつくるしかないのです。そうではないですか。民間の事業者に、短期間でどこまでできるのですか。やはり区がつくるしかないと思うのです。\nそこの姿勢を聞いているのに、総合的にやるのだと、ここでもまたはぐらかす。そういう態度は許せないです。区民に対して、子どもに対して責任を持とうという姿勢が見えません。私は、そこはちゃんと正すべきだと思います。きちんと答えるべきだと思います。繰り返しになりますが、そういう姿勢があるのかどうか、最後に聞いて終わりにしたいと思います。"},{"i":178,"speaker":"金子子ども未来事業部長","text":"先ほどからご意見を伺っていると、はぐらかしや、ごまかしとおっしゃっておりますけれども、私どもはそういうつもりは一切ございません。"},{"i":179,"speaker":"南委員","text":"では、具体的に言ってください。"},{"i":180,"speaker":"金子子ども未来事業部長","text":"静かにしてください。\n私どもとしては、先ほど副委員長が奇しくもおっしゃったとおり、横浜市、千葉市の例を見ても、供給が重要を生むというのは、確実な現象としてあると思っています。今年４月の待機児については、残念ながら品川区は１００人を超えましたけれども、それまでの待機児童の数を見ると、城南地域で２桁だったのは品川区だけだったのです。そういう意味では、城南の地域に住もうとする人、保育のことを考えると、品川区がまず第１の選択肢になるというのは、結構たくさんの方からお聞きしていまして、供給が需要を生む１つの例だろうと思っています。そういう意味では、先ほど副委員長が奇しくもおっしゃったとおり、広域的に広い範囲で自治体が対応していかない限り、やはり難しい問題だなと思っています。\nそれはそれで、一方ありますけれども、品川区としても積極的に取り組んでいくというのは、前々から申し上げているとおり、区の姿勢として待機児童ゼロを目標にして、積極的に取り組んでいく。これが区の姿勢であります。そういう意味では、その手法として総合的に取り組んでまいります。\n先ほども申し上げて、繰り返しになって恐縮ですけれども、私どもは私立も公立も含めて、待機児童対策に取り組んでいくという、前回申し上げたその言葉通り取り組んでいく考えでございます。"},{"i":181,"speaker":"南委員","text":"別の機会に反論します。"},{"i":182,"speaker":"こんの委員長","text":"他にございますでしょうか。\nご発言がないようですので、これで質疑を終了いたします。\nそれでは、本請願の取り扱いについて、ご意見を伺いたいと思います。継続にする、あるいは結論を出す、どちらかご発言願います。\nまた、結論を出すのであれば、その結論についてもご発言ください。\nそれでは、自民党からお願いします。"},{"i":183,"speaker":"渡辺委員","text":"結論を出す。不採択の考えです。\n理由は、請願のタイトルにあるように、認可保育園に特化するものを含めて、先ほど来ご答弁があったように、総合的な施策で、これまでも最善の取組みと私どもは考えております。課題はあるにせよ、今後も総合的な取組みで進むべきものだと思います。"},{"i":184,"speaker":"こんの委員長","text":"公明党。"},{"i":185,"speaker":"つる委員","text":"はい。結論を出すというところで、態度は不採択。\n理由については、趣旨にあるところというのは、日常区民の方々からいただく相談、または対応させていただいていることというのは、よく承知しているところであります。その中で、請願項目、また請願趣旨の下段にあるやり方、対策については、今、渡辺委員からもありましたけれども、それを含む総合的な対策ということで、これまでも過去も含め、そういった形で品川区は待機児童対策を積極的に取り組んでいるという姿勢を示していると理解しているところであります。\nただ、この間、議論があった中で、供給が需要を生むことも含めて、品川区に限らず、他区の課題でもありますし、そうした意味も含めて、その中で品川区は必死になって取り組んでいるのだろうと思っています。\nその中で、あえて言うならば、総合的な対策というところでは、会派としてもいろいろな機会でさまざまな自治体の事例等を紹介して、ハード的なことを整備すると、大きい課題も残るということも含めて、ソフト的なところも提案しているところであります。そうしたことも含めながら、いわゆる総合的な対策で待機児童ゼロを目指していく取組みをやっていくことがいいのであろうと思っています。\nそういった中で、この請願については不採択です。"},{"i":186,"speaker":"こんの委員長","text":"次に、民・改。"},{"i":187,"speaker":"石田（し）委員","text":"結論を出す。不採択であります。\n理由としては、先ほどから皆様がおっしゃっているとおり、我々としても、総合的な保育、また多様な受け皿を持って、保育をしっかり行っていくという考えのもと、認可保育園に特化せず、さまざまな手法で、できる限り待機児ゼロを目指していただいて、さまざまな角度で施策を実行していただければなと思いますので、不採択でお願いしたいと思います。"},{"i":188,"speaker":"こんの委員長","text":"共産党。"},{"i":189,"speaker":"南委員","text":"私は、今日、結論を出していいと思います。態度は採択です。\n今まで、区は待機児童が今年初めて３桁になったとか、それまでは２桁だったとか、そんなことをおっしゃるけれども、待機児童を出すこと自体が、私は本当に大変な事態だと思います。そういう認識があるのであれば、それまでは２桁だったという答弁はあり得ないと思うのです。\n子どもを育てながら働きたいという女性の皆様の力を社会にしっかり引き出させて、健全な社会が発展していくと思うのです。そういう点でも、待機児を出さないという立場にしっかり立つべきだと思います。非常に残念な答弁だと思いました。私の感想です。\nしたがって、そういう状況ではなくて、きちんとした整備をしていく。できるだけ住民の皆様の期待に応えられるような方向で、しかし、ここまで努力したけれどもできないから、ここで我慢してくださいという局面はあると思うのです。そういうこともなく、これだけ努力しているのだということだけでやっていることを見ているということは、私は働く若い子育て世代の区民の皆様には、本当に失礼だと思います。非常に残念です。そのことを申し上げて、採択したいと思います。"},{"i":190,"speaker":"こんの委員長","text":"次に、無所属品川。"},{"i":191,"speaker":"吉田委員","text":"結論を出します。不採択です。\n皆様がおっしゃっていたように、本区では総合的に待機児童ゼロを目指してこれまでも来ましたし、これからもやっていくということで、全区的にも、地域的に広がりを持って進めているということで、今回は不採択といたします。"},{"i":192,"speaker":"こんの委員長","text":"無所属。"},{"i":193,"speaker":"高橋委員","text":"結論を出す。不採択です。\n今、議論にありましたけれども、認可保育園を含めて、さまざまな形態で取り組んできたご説明をいただいています。そういった状況の中で、今後も、そこにありますように、預ける体制を進めてきているところです。\nただ、課題がいくつかあるというお話があったので、新制度のニーズ調査をした部分もあります。スピード感を持って、それから、先ほどソフトの話がありましたけれども、民間の力を導入する、誘導するといった、いろいろな仕組みをやっています。そういった点も検討する中で、これまでのような総合的なものを進めていっていただければと思います。"},{"i":194,"speaker":"こんの委員長","text":"それでは、本請願については、結論を出すとのご意見でまとまったようでございますので、そのような取扱いでよろしいでしょうか。\n〔「はい」と呼ぶ者あり〕"},{"i":195,"speaker":"こんの委員長","text":"ありがとうございます。\nそれでは、本件は本日結論を出すことに決定いたしました。\n先ほどの質疑でそれぞれの方の態度表明、ご意見を伺いましたので、本件につきましては、挙手により採決を行います。\nそれでは、平成２６年請願第２１号 認可保育園大幅増設で待機児ゼロを求める請願を採決いたします。\n本件は、挙手により採決を行います。本件を採択することに賛成の方は、挙手願います。\n〔賛成者挙手〕"},{"i":196,"speaker":"こんの委員長","text":"賛成少数でございます。\nよって、本件は不採択と決定いたしました。\n────────────────────────────────────────────\n(3) 平成２６年請願第２５号 一人ひとりの子どもが大切にされる品川区を求める請願"},{"i":197,"speaker":"こんの委員長","text":"それでは、次に、(3)の平成２６年請願第２５号 一人ひとりの子どもが大切にされる品川区を求める請願を議題に供します。\n本件は初めての審査でありますので、書記に朗読させます。\n〔書記朗読〕"},{"i":198,"speaker":"こんの委員長","text":"朗読が終わりました。\nそれでは、本件につきまして、理事者よりご説明願います。"},{"i":199,"speaker":"今井制度改革・待機児童対策担当課長","text":"それでは、私から、本請願の項目についてご説明いたします。\n請願項目１でございますけれども、品川区におきましては、認可保育園、認証保育所、家庭的保育事業、幼稚園等、さまざまな施設、事業におきまして、教育・保育を実施しており、それぞれの施設や事業に応じて定められております法令や基準を遵守し、子どもが心身ともに健やかに育つよう、保育を実施しているところです。\n２番の項目についてですが、現在実施しております家庭的保育事業に従事する、いわゆる保育ママにつきましても、区が指定する研修を修了した保育士、教員、看護師、助産師または保健師のいずれかの資格を有するということを区長が適当と認める保育ママの要件としてまいりました。今回、新しく区の認可事業となります家庭的保育事業等につきましても、保育士以外の場合の要件として、現行の家庭的保育事業と同様に、幼稚園教諭、看護師、助産師および保健師のいずれかの資格を有する者としております。\n請願の、法の基準より上回る保育者全員は、特に小規模保育Ｂ型を指すと思われますが、区では小規模保育Ｂ型は、国の基準通り保育従事者のうち、保育士の割合を半数以上と規則で定めておりますが、現行通り全ての保育従事者にいずれかの資格を求めているところです。\n次に、項目の３でございますけれども、品川区では、これまで通り、保育の受け入れの拡大につきましては、引き続き認可保育園、認証保育所、小規模保育施設の開設など、総合的な待機児童対策で行ってまいります。その考えに変わりはございません。\n次に、４の項目の保育園の屋外遊技場、そしてその代替地となる公園や広場等につきましては、児童福祉施設の整備および運営に関する基準や通知によりまして、設置が求められております。私どもはそこで行われる保育が、保育所保育指針にのっとったものになるように実践しておりますし、私立にも指導しているところでございます。\n項目の５番でございますが、利用者負担につきましては、新制度のもとでも、保護者の所得に応じた応能負担が原則となります。その額につきましては、現行の水準をもとに国が定める水準を限度として、区が定めるもので、現在、第１回定例会に上程すべく準備を進めております。その額につきましては、現行の額を踏まえ、当面負担が増加しないよう、検討を進めているところです。\n項目の６の新制度の説明につきましては、広報やホームページのほか、区独自のパンフレットを作成し、適宜配布しているところです。\nそれぞれ幼稚園・保育園など、施設長に説明した上で、区民説明会も３回開催いたしました。\nさらに、窓口や電話等で、区民事業者等に個別に相談に応じているとともに、それぞれのニーズに応じた詳細な説明が必要となりますので、これまで通り、引き続き丁寧な対応を行ってまいります。"},{"i":200,"speaker":"こんの委員長","text":"説明が終わりました。本請願につきまして、ご質疑、ご意見等ございましたら、ご発言願います。よろしいでしょうか。"},{"i":201,"speaker":"南委員","text":"今の６番目の説明のところで確認したいのです。幼稚園や保育園の施設長に説明をしている。要するに、一番知りたいのは、預けている父母の皆様です。ですから、その方々に対する既存園の父母に対する説明会というのは、具体的にどういう形で行われているのか、行われようとしているのか、そこを伺いたいと思います。\n先ほど午前中の質疑で、幼稚園の部分では、既存の保育園でもそれぞれが説明するとなっていました。１号と３号の違いはありますけれども、同じ法改正による中身ですから、幼稚園が個別に園ごとにやっているのであれば、保育園も園ごとにやるべきだと思います。したがって、そこについてどういうやり方をしているのかを、１つ確認したいと思います。\nそして、４番目の「園庭や公園・広場などの環境整備をしてください」というところについては、私たち共産党としても、保育園ということは、体、手足を伸ばして遊べる場、あるいは走り回れる場、走り回るという活動は、成長・発達の時期にある子どもにとっては、非常に大事なものだと思うのです。したがって、今、定員を拡大し、表現は悪いですけれども、定員を詰め込んでいる。園舎内に詰め込んでいるという状況の中で、存分に走り回れない、遊び切れないという実態があると思うのです。それだけに、園庭というのは、必要不可欠な条件だと思うので、指針にのっとるよう指導しているというお話なのですけれども、具体的に園庭を設置しろと指導しているのかどうか、その辺を具体的に知りたいと思いますので、教えていただきたいと思います。\nそれから、認可保育園の増設という３番は、先ほどの質疑とダブりますが、総合的にやっていくという話ですけれども、それでは私は困る。不十分で、この要望に応えることにならないと思いますので、それは意見として言っておきます。\nそれと、資格のところなのですが、Ｂ型保育園のところでは、２分の１は有資格でなくてもいいのだと条例にも指定しました。したがって、先ほど区の研修を受けたいろいろな資格の説明をされましたけれども、保育士について２分の１の方たちは、先ほどの説明のどの資格を持っていなくても保育に当たれるのかどうか。その辺を確認したいと思います。"},{"i":202,"speaker":"今井制度改革・待機児童対策担当課長","text":"初めに、１２月１日付で「保護者の皆様へ」という形で、申し込みの際、そして現在、認可保育園に入所をお待ちの方々につきましても発送したところでございます。こちらに、新制度に伴う保育園の利用等につきまして、認定の手続等についても説明をしているところでございます。\nただし、認定の手続は、委員ご案内のとおり、申請と同様に認定の手続ができるような形になっておりますので、在園児も含めて、この通知でお知らせしているところでございます。\n次に、公園などの指導の部分でございますけれども、私どもは厚生労働省の通知にありますとおり、園庭の代替という形で、公園やその他の広場が認められております。私どもが指導しておりますのは、どのような場所を使いましても、保育所保育指針にのっとり、今、委員がおっしゃったような、体を動かしたり、環境に触れたり、さまざまな保育・教育活動が実践できるようにということでお伝えしているところで、園庭必置を求めているものではございません。\n３点目の小規模保育事業につきましては、条例で小規模保育Ｂ型につきましては、保育士の割合は、条例の規則に委任しております。規則につきましては、保育士は半数以上としておりまして、保育士以外の保育従事者の要件につきましては、先ほどご説明した、いずれかの資格を有することと定めております。"},{"i":203,"speaker":"南委員","text":"まず、資格のところからいきますけれども、保育士以外は何らかの資格ということなのです。保育士は、半分の方は資格を持っていない。そういう方でもいいということですね。保育士の２分の１が資格を有していなくても大丈夫で、保育ができると私は理解しているのですけれども、それは違うのですかということを聞きたいのです。確認したいです。\nそれから、園庭の関係ですが、この間、認証保育所、認可保育園も、具体的に中までは入っていないですけれども、１軒１軒確認してきました。園庭にかわる公園や広場が、必ずしもすぐそばにあるところばかりではありません。あるところもあります。園庭のあるところも、園庭と言っていいかどうかは、一人ひとりの感覚ですから、私はなかなかそのように思えないですけれども、そういう保育園もあります。\nしかし、大体のところが園庭にかわる公園・広場、子どもが安全に通え、日常的にそこで手足を伸ばして遊び回れるというスペースは、なかなか確立され切れていません。そういう状況の中で、園庭にかわるというところをどこまで許容範囲とするのか、品川区の見解を伺いたいと思います。\nそれから最後、説明会ですが、私の質問は、保育園に子どもを預けておられる保護者に対して、園として説明会を実施しているのかどうか。保育園ごとにするべきだと思っているのですけれども、そこを聞いたのです。私の理解では、そのように理解できなかったので、申し訳ない、もう一度確認させていただきたいと思います。"},{"i":204,"speaker":"今井制度改革・待機児童対策担当課長","text":"初めに、小規模保育のＢ型というのは、法律上、全員小規模保育に従事する職員は、保育従事者という名称で呼ばれております。保育士の割合が半数以上ということで、これは国のお示しがありましたけれども、区としても規則で定めております。保育士以外の保育従事者は、国は何ら要件を定めていないところでございますけれども、区はこれまでの現行の家庭的保育事業の状況を踏まえて、現行の幼稚園教諭、看護師、助産師、保健師のいずれかの資格を有することとしたものでございます。保育従事者の半数以上が保育士ということでございます。\n次に、公園の考え方につきましては、委員ご案内のとおり、屋上にあっても構わないですとか、いろいろな通知が出ております。\n区としましては、実際に園庭がある保育園であっても、お散歩に行ったりして、いろいろな保育、実践活動をしております。やはり保育所保育指針に定められたさまざまな保育・教育が十分満たされる広さおよび状況を確認しているというところになります。例えば、おトイレや水飲み場があるなど、そのような条件も具体的に国の通知には示されているところでございます。\nそれから、説明会でございますけれども、在籍園児につきましては、それぞれ品川区がつくりました独自のパンフレットを差し上げた後、説明会を開催するかどうかは園にお任せしております。今回、既に認可保育園に申し込んでいる方も、在園児も含めて、「保護者の皆様へ」という形で説明の資料を配布させていただいております。"},{"i":205,"speaker":"南委員","text":"従事者のところは、保育士以外の保育に携わる方は、先ほど説明があった資格を持つ方になっている。必ずしも保育士ではないということです。私は、できるだけ保育士の資格を持つ方が必要だと思っておりまして、そういう方向での指導を、これからの実践の中でしていただきたいと思います。\nそれと、園庭については、日常保育の中で子どもたちが手足を伸ばして遊び回れるスペースという認識で見ると、なかなかそうではないというところなので、これから保育園をたくさんつくってほしいというところで、民間の事業者の方にもお願いせざるを得ないところで、なかなか経費的にも、条件的にも難しいところはあると思います。しかし、欠かせない必須な条件だということで、品川区の基準として、そこは盛り込むべきだと思っています。ぜひ、そういう方向で指導を強めていただけるようにしたいと思っております。\nそれから、３番目の園ごとの説明については、資料を配布したということにとどまっているわけです。園独自の考え方で説明する、しないはお任せしているということなのですが、自分の子どもが今は保育園に入っているから、それはそれで安心なのだけれども、今度の新しい制度でどう変わっていくのかというところは不安なところなので、資料を送ることにとどまらずに、しっかりとした説明をするべきで、不安を解消する上で必要だと思っていますので、そういうこともやっていただきたいと思います。\nそういう点で、この請願については、非常に理解できる内容だと思うし、新しい国との関係の中で、今日的な問題に対しての不安が、そのまま品川区に対応を求めて、頼るところは区しかないということだと思います。こういう請願になってあらわれてきているのだと理解するわけです。ですから、そういう声に応えて対応していただけるようにお願いしておきたいと思います。\nそれから最後に、今、品川区は、いい、悪いは、ある種、私は批判的に見ていますけれども、保育園に預けたいという方に対して、できるだけ詰め込んで、１人でも多くの子どもが入れるようにしたいということで、定員をオーバーして受け入れているということは、切実なお母さんたちの要求から見れば、やむを得ないのかなと思うわけです。\nしかし、それが詰め込み保育という形で、この間の本会議でも指摘させていただきましたけれども、トイレが渋滞する。１歳後半から２歳にかけて、排泄訓練というのは大事なのです。人間として育っていく上で、排泄の訓練をしっかりしないと、排泄機能が育たない。つまり、脳の機能も含めて育っていかないということになるわけで、トイレの訓練というのは、その年齢の保育の中で大事な部分を占めている。\nところが、順番待ちで、自分がトイレに行きたいのに行けない。それで、ついついお漏らしをしてしまう。そのことによる子どもの心理的なダメージがすごく大きいのをご存じですか。そういう問題があるということを、理事者の皆様はご存じでしょうか。\n私はそういう角度から、詰め込みはあまり好ましくない。詰め込むのであれば、それに見合ったトイレならトイレの設備を充実させなければいけないのです。それもしないまま詰め込んでいく。本当に子どもが健全に育っていかない。こういうところからも、私たちは言っているわけです。\nしたがって、必要な手立てもとらないまま、一方的に詰め込むことはやめるべきだと思っているのです。そこのところも意見として述べておきたい。そういう状況の解消を１日も早くしていただきたいということをお願いして、発言を終わりたいと思います。"},{"i":206,"speaker":"こんの委員長","text":"他にご発言ありますでしょうか。\nないようですので、これで質疑を終了いたします。\nそれでは、本請願の取扱いについて、ご意見を伺いたいと思います。継続にする、あるいは結論を出す、どちらかご発言願います。\nまた、結論を出すのであれば、その結論についてもご発言願います。\nそれでは、自民党からお願いします。"},{"i":207,"speaker":"渡辺委員","text":"結論を出す。態度は不採択です。"},{"i":208,"speaker":"こんの委員長","text":"公明党。"},{"i":209,"speaker":"つる委員","text":"結論を出すで、態度は不採択です。\nご答弁を聞いている中で、今回、取り上げるというものではないのかなという判断です。"},{"i":210,"speaker":"こんの委員長","text":"民・改。"},{"i":211,"speaker":"石田（し）委員","text":"結論を出すで、態度は不採択であります。\n理由としては、区側からの説明の中にもあったように、それぞれ法の基準、もしくはそれ以上のことを行っていただいているのではないかなと思います。\nあと、６項目あたりのものですが、現在の考えでは行っていかない。また、区に関しては、丁寧に段階を押さえてやっていただいていると思います。\n３に関しては、先ほどもお話をしましたけれども、認可保育園に特化するものではないという我々の考えのもと、今回の請願は不採択という結論にさせていただきます。"},{"i":212,"speaker":"こんの委員長","text":"共産党。"},{"i":213,"speaker":"南委員","text":"今日中に結論を出し、採択をしたいと思います。\n採択の理由は、先ほどの質疑で述べた通りです。"},{"i":214,"speaker":"こんの委員長","text":"無所属品川。"},{"i":215,"speaker":"吉田委員","text":"結論を出して、不採択です。\n区としても、それぞれの努力をしておりますし、また区については一生懸命やっているということと、３については、先ほどと同じことでございます。"},{"i":216,"speaker":"こんの委員長","text":"無所属。"},{"i":217,"speaker":"高橋委員","text":"結論を出すということで、不採択です。\n１つだけ、６番の新制度についての説明については、おそらく新制度が始まってからも、いろいろご質問があったりするので、先ほどニーズに応じた説明を丁寧にやられているということを伺ったので、その結果をうまく活かして、他の園にも説明していっていただければ、より保護者の方々に周知されると思います。"},{"i":218,"speaker":"こんの委員長","text":"それでは、本請願については、結論を出すとのことでご意見がまとまったようですので、その取扱いでよろしいでしょうか。\n〔「はい」と呼ぶ者あり〕"},{"i":219,"speaker":"こんの委員長","text":"ありがとうございます。\nそれでは、本件は本日結論を出すことに決定いたしました。\n先ほどの質疑でそれぞれの方のご意見を伺いましたので、本件につきましては、挙手により採決を行います。\nそれでは、平成２６年請願第２５号 一人ひとりの子どもが大切にされる品川区を求める請願を採決いたします。\n本件は、挙手により採決を行います。本件を採択することに賛成の方は、挙手願います。\n〔賛成者挙手〕"},{"i":220,"speaker":"こんの委員長","text":"賛成少数でございます。\nよって、本件は不採択と決定いたしました。\n────────────────────────────────────────────\n３ その他"},{"i":221,"speaker":"こんの委員長","text":"次に、その他を議題に供します。\nまず、本定例会の一般質問に係る所管質問ですが、本定例会の一般質問中、文教委員会にかかわる項目について所管質問をなさりたい委員がいらっしゃいましたら、その基礎となる一般質問の項目と、それに関する質問内容をこの場でお願いいたします。\nなお、本会議での質問の繰り返しにならないよう、お願いいたします。質問される委員がいらっしゃる場合は、明日この委員会で理事者からご答弁をいただき、申し出た委員以外の方も議論に加わっていただくという形で進めていきたいと思います。\nそれでは、所管質問がございましたら、ご発言願います。よろしいでしょうか。\n〔「なし」と呼ぶ者あり〕"},{"i":222,"speaker":"こんの委員長","text":"いらっしゃらないようですので、一般質問に係る所管質問については終了いたします。\nその他に何かございますでしょうか。\nそれでは、以上でその他を終了いたします。\n以上で、本日の予定は全て終了いたしました。明日も午前１０時から開会でございます。これをもちまして、文教委員会を閉会いたします。\n○午後 ２時１５分閉会"}]});
